(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c6"]=[{"id":"00014675","register_sub_id":"101","register_pk":"515217","name":"井原市民会館本館","kana":"いばらしみんかいかんほんかん","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和後","pref":"岡山県","address":"岡山県井原市井原町311-1","lat":34.59807778,"lng":133.46438333,"geo_status":"db","era":"昭和46年／平成18年改修","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"鉄筋コンクリート造2階建一部3階建、建築面積1，661㎡","structure_material":"鉄筋コンクリート造2階建一部3階建","registered":"2023.08.07(令和5.08.07)","register_no":"33 - 0356","desc":"市中心部の行政・文化施設が並ぶ一画に建つ鉄筋コンクリート造の市民会館。型枠や斫り仕上による、異なる表情のコンクリート打放し仕上を内外に散りばめ、正面に高い時計塔を屹立させ、バルコニーと軒による水平ラインとの交差を意匠的アクセントとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014675"},{"id":"00015229","register_sub_id":"101","register_pk":"530653","name":"岡山県庁議会棟旧館","kana":"おかやまけんちょうぎかいとうきゅうかん","category":"官公庁舎","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"岡山県","address":"岡山県岡山市北区内山下二丁目4-101","lat":34.66135,"lng":133.93438333,"geo_status":"db","era":"昭和32年／令和6年改修","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積1，073㎡、渡り廊下付","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0371","desc":"本庁舎本館の南西に渡り廊下で連絡する議会棟。設計は前川國男。鉄筋コンクリート造、地上三階地下一階建で、三階は四周を張出す。躯体の打放仕上、黒色サッシュ、橙色の特殊ホローブリックなど本館共通の意匠でまとめる。前川による戦後の庁舎建築の秀作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015229"},{"id":"00015230","register_sub_id":"101","register_pk":"530654","name":"岡山県庁西庁舎","kana":"おかやまけんちょうにしちょうしゃ","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和後","pref":"岡山県","address":"岡山県岡山市北区内山下二丁目4-101","lat":34.66155833,"lng":133.93410278,"geo_status":"db","era":"昭和46年／平成16年・令和6年改修","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"鉄筋コンクリート造地上5階地下1階建、建築面積702㎡、塔屋付","structure_material":"鉄筋コンクリート造地上5階地下1階建","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0372","desc":"本庁舎本館と議会棟の西側に位置する庁舎。設計は前川國男。鉄筋コンクリート造、地上五階地下一階建。三階以上は外壁を張出し、西正面は手摺などで格子状に割付け軽快な立面とする。外壁打放仕上や黒色サッシュなど本庁舎に通じる意匠で調和を図った増築棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015230"},{"id":"00015228","register_sub_id":"101","register_pk":"530652","name":"岡山県庁本庁舎本館","kana":"おかやまけんちょうほんちょうしゃほんかん","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和中","pref":"岡山県","address":"岡山県岡山市北区内山下二丁目4-101","lat":34.661725,"lng":133.93469722,"geo_status":"db","era":"昭和32年／昭和39年・同43年増築、平成8年・令和6年改修","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地上9階地下1階建、建築面積1，774㎡、塔屋及び正面回廊付","structure_material":"鉄骨鉄筋コンクリート造地上9階地下1階建","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0370","desc":"岡山城二の丸跡に位置する県庁舎。鉄骨鉄筋コンクリート造、地上九階地下一階建で北に回廊をコの字に突出。下層は躯体を打放仕上、上層は黒色枠カーテンウォールとし、中央部のピロティや回廊で内外を一体として巧みに調和。前川による戦後庁舎建築の大作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015228"},{"id":"00000607","register_sub_id":"101","register_pk":"101597","name":"海遊文化館（旧牛窓警察署本館）","kana":"かいゆうぶんかかん（きゅううしまどけいさつしょほんかん）","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県瀬戸内市牛窓町牛窓3056","lat":34.61583578,"lng":134.16399913,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積247㎡","structure_material":"木造平屋建","registered":"1998.07.23(平成10.07.23)","register_no":"33 － 0019","desc":"地元の実業家，政治家であった香川真一が，自ら設計し私財を投じ建てたもの。正面玄関のペジメントや主翼棟などに各種洋窓を開く外観に特徴がある。小屋組は和小屋であるが，外壁は漆喰モルタルで隅を石積風に見せる等随所に工夫が見られる。施工は森円吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000607"},{"id":"00005505","register_sub_id":"101","register_pk":"106493","name":"加茂川歴史民俗資料館（旧加茂葉たばこ取扱所）","kana":"かもがわれきしみんぞくしりょうかん（きゅうかもはたばことりあつかいしょ）","category":"官公庁舎","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県加賀郡吉備中央町下加茂1103-8","lat":34.86058918,"lng":133.8125918,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積476㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"33 － 0113","desc":"明治２９年の「葉煙草専売法」公布に伴い設置された桁行２９ｍの長大な木造平屋建の施設。屋根は和小屋組の寄棟造，桟瓦葺，外壁を押縁下見板張とし，当初は後方に建物が連続していた。全国有数の葉たばこの産地であった当地域の歴史を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005505"},{"id":"00011402","register_sub_id":"101","register_pk":"209239","name":"旧勝田郡役所庁舎","kana":"きゅうかつたぐんやくしょちょうしゃ","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県勝田郡勝央町勝間田字上ノ町635","lat":35.038676,"lng":134.115499,"geo_status":"db","era":"明治45／昭和18・同29増築、同57改修","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、瓦葺、建築面積413㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"33－0274","desc":"木造二階建の郡役所庁舎。正面中央玄関上部を塔屋とし、その背後から西寄りのみ二階建として二階に議場を配す。塔屋以外は桟瓦葺で、外壁は下見板張とするが、一・二階腰部を竪羽目板張としてアクセントをつける。地方における行政庁舎の近代化の様相を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011402"},{"id":"00013449","register_sub_id":"101","register_pk":"368534","name":"旧倉敷市庁舎（倉敷市立美術館）","kana":"きゅうくらしきしちょうしゃ（くらしきしりつびじゅつかん）","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和中","pref":"岡山県","address":"岡山県倉敷市中央二丁目236-3","lat":34.59466667,"lng":133.76889722,"geo_status":"db","era":"昭和35年／昭和58年改修","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積1985㎡、塔屋付","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2020.08.17(令和2.08.17)","register_no":"33 － 0336","desc":"倉敷の中心部に建つ、鉄筋コンクリート造の庁舎。地上３階地下１階建で、プレストレストコンクリート梁を多用し、約２０メートルの大スパンを実現した。コンクリート打放し仕上の平滑な架構構成を立面に見せた、丹下健三によるモダニズム庁舎建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013449"},{"id":"00009063","register_sub_id":"101","register_pk":"162423","name":"旧専売局味野収納所山田出張所庁舎","kana":"きゅうせんばいきょくあじのしゅうのうしょやまだしゅっちょうしょちょうしゃ","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県玉野市山田字砂新田3218-5","lat":34.54709281,"lng":133.99249179,"geo_status":"db","era":"明治41年／昭和前期・平成12年・平成23年改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積236㎡、渡り廊下付","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"33 － 0250","desc":"川岸に西面して建つ。木造平屋建、建築面積２３６㎡。南北棟の寄棟造桟瓦葺を主棟とし、南東隅から東に寄棟造、北面に切妻造の角屋を出し、正面に切妻屋根の玄関を突き出す。変化のある屋根構成と外壁の白色下見板張が明るく軽快な姿をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009063"},{"id":"00009064","register_sub_id":"101","register_pk":"162424","name":"旧専売局味野収納所山田出張所文庫","kana":"きゅうせんばいきょくあじのしゅうのうしょやまだしゅっちょうしょぶんこ","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県玉野市山田字砂新田3218-5","lat":34.547031,"lng":133.99265249,"geo_status":"db","era":"明治41年／平成19年改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積27㎡","structure_material":"煉瓦造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"33 － 0251","desc":"庁舎の東に建つ。桁行６．０ｍ梁間４．５ｍの煉瓦造で、切妻造桟瓦葺である。西面に石段を付け、出入口を開ける。欠円アーチ窓を妻面中央に穿つ。内部は板床で洋小屋を現し、壁を漆喰塗とする。要所に切石を配し、煉瓦との対比が印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009064"},{"id":"00000311","register_sub_id":"101","register_pk":"101301","name":"佐伯町ふる里会館（旧和気郡山田村役場庁舎）","kana":"さえきちょうふるさとかいかん（きゅうわけぐんやまだむらやくばちょうしゃ）","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県和気郡和気町岩戸725-1","lat":34.85080858,"lng":134.11630322,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造一部木造2階建，建築面積80㎡","structure_material":"鉄筋コンクリート造一部木造2階建","registered":"1997.09.03(平成9.09.03)","register_no":"33 － 0017","desc":"中央部をわずかに高くし，玄関ポーチを付け正面性を強調した左右対称の外観を持つ鉄筋コンクリート造の旧村役場。要所に曲線を用いる等，表現主義の影響がみられる。地方における鉄筋コンクリート造の建物の初期の事例として注目に値する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000311"},{"id":"00005356","register_sub_id":"101","register_pk":"106344","name":"総社市まちかど郷土館（旧総社警察署）","kana":"そうじゃしまちかどきょうどかん（きゅうそうじゃけいさつしょ）","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県総社市総社2-17-33","lat":34.67553614,"lng":133.75444555,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積115㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"33 － 0102","desc":"敷地東面が総社宮参道に接する角地に建つ。桁行７間，梁行４間半で，寄棟造，桟瓦葺の木造２階建で，東南隅に宝形造，八角形状の塔を配す。基礎は煉瓦積，外装下見板張で，柱形や襷形を現し，開口部廻りに装飾を施す。近代の警察署の建築として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005356"},{"id":"00005903","register_sub_id":"101","register_pk":"106888","name":"津山郷土博物館（旧津山市庁舎）","kana":"つやまきょうどはくぶつかん（きゅうつやましちょうしゃ）","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県津山市山下92","lat":35.06082659,"lng":134.00584155,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積586㎡、塔屋付","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2006.10.18(平成18.10.18)","register_no":"33 － 0114","desc":"市の中心部に位置する，鉄筋コンクリート造３階建の庁舎建築。中央正面に車寄を付け，背面には議場を張り出す。腰に花崗岩を貼り，頂部にはスクラッチタイル貼のパラペットを四周に巡らす。中央に５層の塔屋を設け中心性を強調した左右対称の外観が特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005903"},{"id":"00005500","register_sub_id":"101","register_pk":"106488","name":"真鍋家住宅旧郵便局舎","kana":"まなべけじゅうたくきゅうゆうびんきょくしゃ","category":"官公庁舎","subcategory":"建築物","type_guess":"郵便局","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県笠岡市真鍋島4026-1","lat":34.35486162,"lng":133.57733266,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積40㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"33 － 0108","desc":"主屋北面の西側に接して建つ。木造２階建，切妻造，桟瓦葺で，２階外壁をモルタル塗とし，縦長窓を配する。街路に面した西面が正面になり，１，２階境に小庇をつけ，中央には玄関の切妻造屋根を設ける。島内では数少ない洋風意匠で，近代化の足跡を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005500"},{"id":"00015511","register_sub_id":"101","register_pk":"533526","name":"イシネ事務機社屋（旧尾道警察署庁舎）","kana":"いしねじむきしゃおく（きゅうおのみちけいさつしょちょうしゃ）","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県尾道市古浜町27-143","lat":34.39909167,"lng":133.17396944,"geo_status":"db","era":"明治40年／昭和30年移築、同53年改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、瓦葺、建築面積248㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"34 - 0322","desc":"市街地西部に位置し、通りに北面して建つ事務所。旧尾道警察署庁舎を移築改修した木造2階建寄棟造で、大棟両端にフィニアルを据え、正面はモルタル塗とし上下窓を並べる。小屋は梁間10メートル超のキングポスト・トラス。地域の歴史を伝える貴重な事務所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015511"},{"id":"00014412","register_sub_id":"101","register_pk":"511401","name":"旧尾道市役所百島支所庁舎","kana":"きゅうおのみちしやくしょももしまししょちょうしゃ","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和中","pref":"広島県","address":"広島県尾道市百島町字郷1316-1","lat":34.37449722,"lng":133.27259722,"geo_status":"db","era":"昭和29年／令和元年改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積251㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"34 - 0302","desc":"百島北東部にある役場庁舎。木造二階建、半切妻造、外壁モルタル塗で腰洗出し仕上、縦長窓を基調に洋風とし、正面頂部ガラリと二階の四連窓が特徴的。二階の桟敷とステージ付大広間をキングポスト・トラスで実現。一階カウンター付事務室が往時を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014412"},{"id":"00008169","register_sub_id":"101","register_pk":"132610","name":"旧筒賀村役場庁舎","kana":"きゅうつつがそんやくばちょうしゃ","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県山県郡安芸太田町大字中筒賀字市1693-1","lat":34.56170535,"lng":132.24659234,"geo_status":"db","era":"昭和11年／平成5年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積247㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"34 － 0094","desc":"県西部の山間に東面して建つ。正面１６ｍ奥行１５ｍ、宝形造の木造２階建で、正面中央に半円アーチ形開口部をもつ玄関ポーチを付ける。外装モルタル塗仕上げ、腰スクラッチタイル貼とし、櫛形ペディメントには植物文様をあしらう。山間村落の近代化を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008169"},{"id":"00011197","register_sub_id":"101","register_pk":"205304","name":"旧広島県西条清酒醸造支場煙突","kana":"きゅうひろしまけんさいじょうせいしゅじょうぞうしじょうえんとつ","category":"官公庁舎","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県東広島市西条上市町957","lat":34.429011,"lng":132.748841,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造、高さ19m","structure_material":"鉄筋コンクリート造","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0190","desc":"醸造蔵に附属する煙突で、醸造蔵の南に立つ。鉄筋コンクリート造の丸型煙突で、基部の直径は約一・三メートル、高さは約一九メートルとなる。大阪鐡筋混凝土工務所の施工。醸造蔵とともに、西条の鉄筋コンクリート造施設としては最も古いものの一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011197"},{"id":"00011196","register_sub_id":"101","register_pk":"205303","name":"旧広島県西条清酒醸造支場醸造蔵","kana":"きゅうひろしまけんさいじょうせいしゅじょうぞうしじょうじょうぞうぐら","category":"官公庁舎","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県東広島市西条上市町957","lat":34.429143,"lng":132.748845,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積396㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0189","desc":"本館の東方、賀茂泉酒造火蔵の南方に東西棟で建つ。南には下屋を架けて張り出す。鉄筋コンクリート造二階建の醸造蔵で、小屋は鋼製のアングル材を用いてキングポストトラスに組む。西条の醸造施設としては最も古い鉄筋コンクリート造施設のひとつとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011196"},{"id":"00011195","register_sub_id":"101","register_pk":"205302","name":"旧広島県西条清酒醸造支場精米所","kana":"きゅうひろしまけんさいじょうせいしゅじょうぞうしじょうせいまいじょ","category":"官公庁舎","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市西条上市町957","lat":34.428948,"lng":132.748638,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、スレート葺、建築面積138㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0188","desc":"本館の南に渡り廊下を介して接続して建つ。南北棟の平屋建であるが、酒造用の精米機の高さにあわせて棟の高さを違え、南に向けて三段に高めてゆく特徴的な立面を持つ。外壁を横板壁とし、切妻造の屋根頂部にはフィニアルを掲げて洋風意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011195"},{"id":"00011194","register_sub_id":"101","register_pk":"205301","name":"旧広島県西条清酒醸造支場本館","kana":"きゅうひろしまけんさいじょうせいしゅじょうぞうしじょうほんかん","category":"官公庁舎","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県東広島市西条上市町957","lat":34.429096,"lng":132.748627,"geo_status":"db","era":"昭和3頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積101㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0187","desc":"広島県食品工業試験場の支場として開設された。賀茂泉酒造の南に敷地を構える。本館は北面して建つ南北棟半切妻の二階建洋館で、もとは一階が実験室、二階が事務室である。正面には付柱に庇を設け、ポーチとする。醸造技術開発の拠点として用いられた施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011194"},{"id":"00011198","register_sub_id":"101","register_pk":"205305","name":"旧広島県西条清酒醸造支場門柱","kana":"きゅうひろしまけんさいじょうせいしゅじょうぞうしじょうもんちゅう","category":"官公庁舎","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市西条上市町957","lat":34.429205,"lng":132.748646,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"コンクリート造、間口4.6m","structure_material":"コンクリート造","registered":"2016.08.01(平成28.08.01)","register_no":"34 - 0191","desc":"旧広島県西条清酒醸造支場の正門として立てられた。鉄筋コンクリート造の門柱で、表面は洗い出し仕上げとする。側面の隅部には三段の段繰を施して装飾とする。門柱の上部には照明用ブラケットの金具があり、もとは上部に照明がついていたとみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011198"},{"id":"00008774","register_sub_id":"101","register_pk":"149495","name":"上下町商工会館(旧上下警察署庁舎)","kana":"じょうげちょうしょうこうかいかん（きゅうじょうげけいさつしょちょうしゃ）","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県府中市上下町上下字下沖883-1","lat":34.69600133,"lng":133.11846065,"geo_status":"db","era":"昭和5年／昭和中期・昭和57年改修","year":1930,"year_source":"converted","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積101㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"34 － 0115","desc":"上下町市街の道路沿いに建ち、桁行13ｍ梁間7.4ｍ、木造2階建、寄棟造鉄板葺である。正面中央に張出した玄関ポーチの上部を塔屋状に立ち上げ、外壁は2連または3連の縦長窓を配置する。鉄筋コンクリート造の外観形式を木造で表現した、もと警察署庁舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008774"},{"id":"00010061","register_sub_id":"101","register_pk":"196208","name":"福山市旧山野村役場","kana":"ふくやましきゅうやまのむらやくば","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県福山市山野町大字山野字殿川内3782","lat":34.653806,"lng":133.39018522,"geo_status":"db","era":"明治25／昭和53改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、瓦葺、建築面積217㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"34 － 0139","desc":"木造二階建、入母屋造桟瓦葺で、三面に下屋を廻す。大棟側面の板瓦には「波に鯉」の図様を表し、鬼瓦にも意匠を凝らす。内部は一階が旧執務室で、二階は旧議場で南端を吹抜とする。化粧屋根裏で垂木は半割丸太とする。県東部では現存最古の役場庁舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010061"},{"id":"00001533","register_sub_id":"101","register_pk":"102523","name":"旧岩国税務署","kana":"きゅういわくにぜいむしょ","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県岩国市岩国3-13-9","lat":34.16249493,"lng":132.18531728,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積202㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"35 － 0033","desc":"西岩国駅から岩国市街に入る入口部に立地する木造２階建，モルタル塗の庁舎建築。間口１０間半，総２階建で，正面中央に玄関を置き，左右の端部を薄く張り出して切妻をみせるルネサンス様式的な建築構成をとる。設計は税務監督局技手田中俊郎と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001533"},{"id":"00015387","register_sub_id":"101","register_pk":"532511","name":"旧小川村役場庁舎","kana":"きゅうおがわむらやくばちょうしゃ","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県萩市大字中小川字三明中620-8","lat":34.59147778,"lng":131.67927222,"geo_status":"db","era":"昭和7年／平成7年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階一部平屋建、人工スレート葺、建築面積175㎡","structure_material":"木造2階一部平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"35 - 0137","desc":"集落北側の高台に建つ旧役場庁舎。木造二階建寄棟造東西棟で正面に腰折軒破風をみせ、玄関ポーチを付す。内部は一階に執務室や村長室、二階に議場を配す。一・二階通しの柱形と縦長窓を配し、隅上部に三段の水平帯を廻らすなどセセッション風意匠の庁舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015387"},{"id":"00005921","register_sub_id":"101","register_pk":"106906","name":"旧山口電信局舎","kana":"きゅうやまぐちでんしんきょくしゃ","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県山口市白石一丁目２３２２","lat":34.17743922,"lng":131.47257603,"geo_status":"db","era":"明治6","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造2階建、瓦葺、建築面積74㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"35 － 0049","desc":"東京長崎間の電信線架設の際に建築。木造２階建，方形造，桟瓦葺。外壁は下見板張で，軒蛇腹と胴蛇腹を飾り，鎧戸付の両開窓を開く。玄関ポーチと一部の窓，内部を改修しているが，初期洋風建築の意匠を良好に保持する。電信事業の草創期を伝える遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005921"},{"id":"00002312","register_sub_id":"101","register_pk":"103302","name":"下関南部町郵便局庁舎（旧赤間関郵便電信局）","kana":"しものせきなべちょうゆうびんきょくちょうしゃ（きゅうあかまがせきゆうびんでんしんきょく）","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県下関市南部町22-8","lat":33.956745,"lng":130.941772,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積477㎡","structure_material":"煉瓦造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"35 － 0040","desc":"現存最古の現役郵便局舎。逓信技師三橋四郎の設計による本格的ルネサンス様式の煉瓦造庁舎建築で，明治３０年代前半における西洋建築意匠修得の技術水準を示す作品とされる。近年，構造補強と復元工事がなされ，往時の端整なファサードが回復された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002312"},{"id":"00011563","register_sub_id":"101","register_pk":"210390","name":"永山本家酒造場事務所（旧二俣瀬村役場庁舎）","kana":"ながやまほんけしゅぞうじょうじむしょ（きゅうふたまたせそんやくばちょうしゃ）","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県宇部市大字車地字川部138-1","lat":34.05736194,"lng":131.29052389,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積121㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"35-0095","desc":"厚東川左岸の旧道沿いに建つ。木造二階建、切妻造桟瓦葺で、外壁は石造風に目地を切ったモルタル塗とし、正面中央玄関上部にペディメントを設け、玄関両脇と建物四隅に柱形を付す。内部は一階は事務室、二階は一室の議事堂とするなど、役場の特徴を良く残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011563"},{"id":"00000228","register_sub_id":"101","register_pk":"101218","name":"むつみ村役場旧庁舎","kana":"むつみそんやくばきゅうちょうしゃ","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県萩市大字吉部上3276-1","lat":34.4378179,"lng":131.57733907,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造2階建，瓦葺，建築面積233㎡","structure_material":"木造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"35 － 0004","desc":"木造、２階建の寄棟造、妻入の庁舎。正面に入母屋屋根の玄関、左右に庇が付く。一階の内部は、概ね左右対称形の平面になり、中央の通路が奥手の板敷の執務室にくい込む独特の構成になる。明治期の役場建築遺構として今なお親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000228"},{"id":"00000229","register_sub_id":"101","register_pk":"101219","name":"むつみ村役場土蔵","kana":"むつみそんやくばどぞう","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県萩市大字吉部上3276-1","lat":34.43799625,"lng":131.57722611,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造2階建，瓦葺，建築面積58㎡","structure_material":"木造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"35 － 0005","desc":"旧庁舎の背後に建つ２階建、妻入の中規模の土蔵。本庁舎完成後に建築された。屋根は本庁舎とも石州瓦を葺く。外壁は漆喰仕上げとするが腰下は板張りとし、正面扉口に切妻の庇屋根が付く。本庁舎とともに旧形を保つ点に価値があり、村の象徴となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000229"},{"id":"00008376","register_sub_id":"101","register_pk":"134018","name":"旧川口郵便局局舎及び主屋","kana":"きゅうかわぐちゆうびんきょくきょくしゃおよびしゅおく","category":"官公庁舎","subcategory":"建築物","type_guess":"郵便局","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市山城町大川持字中ハシ584-1","lat":33.96176945,"lng":133.75412104,"geo_status":"db","era":"明治38年／昭和54年改修","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造2階一部地下1階建、瓦葺、建築面積120㎡","structure_material":"木造2階一部地下1階建","registered":"2010.09.10(平成22.09.10)","register_no":"36 － 0081","desc":"川沿いの集落中央に、通りに西面して建つ。南に洋館の局舎、北に和館の主屋を配する。木造２階建で、洋館の寄棟屋根に切妻屋根がＴ字型に取り付く。洋館は下見板張のペンキ塗、窓や軒まわりに意匠を凝らし、和館は出格子などを構え、落ち着きのある外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008376"},{"id":"00008067","register_sub_id":"101","register_pk":"128898","name":"旧三野町役場庁舎","kana":"きゅうみのまちやくばちょうしゃ","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県三好市三野町芝生1039","lat":34.04202903,"lng":133.97058252,"geo_status":"db","era":"昭和9／昭和52改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、スレート葺、建築面積155㎡","structure_material":"木造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"36-0080","desc":"旧三野町を東西に貫く旧県道に南面して建つ。正面１５ｍの木造２階建で、中央及び両翼の正面側に張出部をつける。正面外観は左右対称で、２階には半円アーチ窓を開ける。中央張出部の腰折屋根や、独特の意匠をもつ付柱などが異彩を放つ洋風庁舎である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008067"},{"id":"00012657","register_sub_id":"101","register_pk":"367951","name":"古本家住宅旧郵便局","kana":"ふるもとけじゅうたくきゅうゆうびんきょく","category":"官公庁舎","subcategory":"建築物","type_guess":"郵便局","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県三好市池田町佐野金氏935-1","lat":34.003742,"lng":133.703568,"geo_status":"geocoded","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"コンクリートブロック造平屋建、金属板葺、建築面積29㎡","structure_material":"コンクリートブロック造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"36 － 0190","desc":"主屋東南隅に接続し、敷地正面の角地に建つ。基礎は野面積、外壁は淡黄色の人造石塗洗出し仕上で、石造風に目地を切る。西南隅の出入口周辺の装飾や窓枠、窓桟はアール・デコ風である。昭和初期の地方局舎の様相を伝え、集落景観のアクセントになっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012657"},{"id":"00008068","register_sub_id":"101","register_pk":"128899","name":"旧引田郵便局局舎","kana":"きゅうひけたゆうびんきょくきょくしゃ","category":"官公庁舎","subcategory":"建築物","type_guess":"郵便局","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県東かがわ市引田字畑方2253","lat":34.22723074,"lng":134.40370679,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積80㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"37-0334","desc":"旧引田町中心街に立地し、東面して建つ。桁行１２ｍ梁間６．５ｍ、寄棟造の木造平屋建。外壁はタイル貼及びモルタル塗洗出しで、頂部に「〒」マークをあしらう半円形ペディメントを付け、正面及び側面の三方に八角形の窓を左右対称に配す瀟洒な造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008068"},{"id":"00001728","register_sub_id":"101","register_pk":"102718","name":"四国村潟元消防組第四部新馬場消防屯所","kana":"しこくむらかたもとしょうぼうぐみだいよんぶしんばばしょうぼうとんしょ","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県高松市屋島中町125","lat":34.34435776,"lng":134.10930852,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積11㎡、石柱付","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"37 － 0028","desc":"もとは地元の屋島中町新馬場に所在した消防車庫。木造、平屋建、桁行２間梁行１間半の規模で、寄棟造、瓦葺、妻入とする。外周３面は縦板張りで、正面に幅一杯の上半分を連子にした両開き戸を付ける。小規模ながら端整な姿形をした消防車庫である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001728"},{"id":"00000104","register_sub_id":"101","register_pk":"101094","name":"宇和島市立歴史資料館（旧宇和島警察署）","kana":"うわじましりつれきししりょうかん（きゅううわじまけいさつしょ）","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県宇和島市住吉町２-４-36","lat":33.22645051,"lng":132.55466971,"geo_status":"db","era":"明治17","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造2階建、瓦葺、建築面積214㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"38 － 0001","desc":"市内広小路に警察署として建設されたもので，棟梁稲垣弥吉が工事にあたった。１・２階を通したペディメントを持つ玄関ポーチ，上下窓，軒蛇腹等を備え，本格的な洋風の意匠を持つ。当地方では先駆的な本格的洋風建築で，棟梁の技術技能の高さを伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000104"},{"id":"00013762","register_sub_id":"101","register_pk":"504980","name":"愛媛県庁本館","kana":"えひめけんちょうほんかん","category":"官公庁舎","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛媛県","address":"愛媛県松山市一番町四丁目4-2","lat":33.84163889,"lng":132.76569722,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造4階建、陸屋根、建築面積2，104㎡、塔屋付","structure_material":"鉄筋コンクリート造4階建","registered":"2021.02.26(令和3.02.26)","register_no":"38 － 150","desc":"Ｈ形平面の鉄筋コンクリート造四階建県庁舎。中央の車寄上部に三連の半円アーチを並べ、頂部にドームを冠した塔屋を載せて両翼を張出す。外観は石積と平滑な擬石仕上とし、装飾を車寄開口と窓廻りの縁取に留めるが、内部は中央階段室や正庁等を華麗に飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013762"},{"id":"00009223","register_sub_id":"101","register_pk":"164776","name":"鬼北町庁舎","kana":"きほくちょうちょうしゃ","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和中","pref":"愛媛県","address":"愛媛県北宇和郡鬼北町大字近永800-1","lat":33.25698622,"lng":132.68432091,"geo_status":"db","era":"昭和33年","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積579㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"東西42メートル南北13.5メートル、鉄筋コンクリート造3階建、陸屋根である。正方形平面の3階議場の屋根に、当時最新技術であった双曲放物面シェル構造を採用し、妻壁に円形ガラスブロックを嵌める。レーモンド建築設計事務所による庁舎建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009223"},{"id":"00001759","register_sub_id":"101","register_pk":"102749","name":"長浜町庁舎","kana":"ながはまちょうちょうしゃ","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県大洲市長浜甲480-3","lat":33.613845,"lng":132.479538,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積382㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"38 － 0008","desc":"伊予灘に注ぐ肱川の河口に位置する長浜の市街地に建つ。木造総２階建，入母屋造・桟瓦葺で，正面の中央玄関の上部に切妻破風を設け，２階の丸柱で支えられた半円形のモチーフを飾る。外壁の腰部を御影石を貼るなど，昭和初期の洋風庁舎建築の一事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001759"},{"id":"00005507","register_sub_id":"101","register_pk":"106495","name":"松山地方気象台（旧愛媛県立松山測候所）庁舎","kana":"まつやまちほうきしょうだい（きゅうえひめけんりつまつやまそっこうじょ）ちょうしゃ","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県松山市北持田町102","lat":33.84371574,"lng":132.77757297,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階一部平屋建、建築面積340㎡、塔屋付","structure_material":"鉄筋コンクリート造2階一部平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"38 － 0070","desc":"南面する鉄筋コンクリート造庁舎。正面中央が玄関を備えた塔屋付３階建，西側が２階建，東側がフィンクトラス小屋組で切妻造屋根の平屋建とする。軽快に配された縦長窓，石張風の外壁，中央３階にあるメダイオンや帯状タイルなど，全体に装飾性に富んでいる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005507"},{"id":"00005206","register_sub_id":"101","register_pk":"106196","name":"大牟田市役所本庁舎旧館","kana":"おおむたしやくしょほんちょうしゃきゅうかん","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県大牟田市有明町2-3","lat":33.030247,"lng":130.445984,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造4階建、建築面積1378㎡、塔屋付","structure_material":"鉄筋コンクリート造4階建","registered":"2005.12.26(平成17.12.26)","register_no":"40 － 0041","desc":"ＪＲ大牟田駅前に位置する。正面を６２ｍとしたＲＣ造４階建の庁舎建築で，中央背面に議場を張り出す。縦長窓を密に配した採光に配慮したつくりで，複数の蛇腹と中央部の柱形で外観を引きしめる。正面中央部には５層の塔屋を設け，中心性を強調する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005206"},{"id":"00012458","register_sub_id":"101","register_pk":"531782","name":"折尾愛真学園記念館（旧折尾警察署庁舎）","kana":"おりおあいしんがくえんきねんかん（きゅうおりおけいさつしょちょうしゃ）","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県北九州市八幡西区堀川町823-1","lat":33.85966111,"lng":130.7093,"geo_status":"db","era":"明治42年／昭和16年・同61年移築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積138㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"40-153","desc":"キャンパスの南西隅に東面して建つ。寄棟造桟瓦葺の総二階建で、外壁下見板張とし、南側面に階段室、正面中央に切妻屋根の玄関ポーチを出す。上下階とも大部屋中心の明瞭な構成で、装飾も簡明である。明治時代に各地で建てられた洋風公共施設の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012458"},{"id":"00009403","register_sub_id":"101","register_pk":"194196","name":"旧小倉警察署庁舎（旧岡田医院）","kana":"きゅうこくらけいさつしょちょうしゃ（きゅうおかだいいん）","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県北九州市小倉北区室町2-42-8","lat":33.8862864,"lng":130.87634958,"geo_status":"db","era":"明治23年／昭和4年・昭和後期・平成18年改修","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造2階建、瓦葺、建築面積162㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"40 － 0080","desc":"紫川畔の角地に建つ。木造二階建、建築面積一六二平方メートル、寄棟造桟瓦葺で、南角に張出す玄関に円柱で支持した庇を付す。外壁は横板張で上げ下げ窓を連続させ、軒に蛇腹を廻らすなど洋風意匠とする。建築年代の明らかなものとして県内最古の庁舎建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009403"},{"id":"00001308","register_sub_id":"101","register_pk":"102298","name":"門司区役所（旧門司市役所）","kana":"もじくやくしょ（きゅうもじしやくしょ）","category":"官公庁舎","subcategory":"建築物","type_guess":"門・塀","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県北九州市門司区清滝1-1-1","lat":33.94118327,"lng":130.95965925,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造３階建，建築面積1854㎡","structure_material":"鉄筋コンクリート造３階建","registered":"1999.08.23(平成11.08.23)","register_no":"40 － 0010","desc":"門司港とJR門司港駅を見下ろす丘の上に建つ。玄関ポーチなどに装飾的要素を残すものの、全体としては無装飾のインターナショナルスタイルを基調とする。左右対称で建物の隅を曲線で処理しているのが特徴。設計は九州帝大建築課長であった倉田謙による。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001308"},{"id":"00006112","register_sub_id":"101","register_pk":"107096","name":"宇城市国際交流村重要資料展示室（旧三角簡易裁判所記録倉庫）","kana":"うきしこくさいこうりゅうむらじゅうようしりょうてんじしつ（きゅうみすみかんいさいばんしょきろくそうこ）","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県宇城市三角町三角浦1031","lat":32.62334587,"lng":130.45643769,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積45㎡","structure_material":"煉瓦造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"43 － 0089","desc":"港を一望する高台に位置し，東を正面とし，中央に起り破風の車寄を突き出す。寄棟造，桟瓦葺の木造平屋建で，東北隅に法廷を配する。外観は真壁造で，腰縦羽目，上部下見板張，小壁白漆喰塗とする。司法省営繕による和風色の強い地方裁判所庁舎建築の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006112"},{"id":"00006113","register_sub_id":"101","register_pk":"107097","name":"宇城市国際交流村伝統工芸館（旧三角簡易裁判所弁護士等控室）","kana":"うきしこくさいこうりゅうむらでんとうこうげいかん（きゅうみすみかんいさいばんしょべんごしとうひかえしつ）","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県宇城市三角町三角浦1031","lat":32.62351504,"lng":130.45672548,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積75㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"43 － 0088","desc":"本館の北方に東西棟で建ち，庁舎とは渡廊下で結ばれる。桁行７間半，梁間２間，寄棟造，桟瓦葺の木造平屋建で，南面に土庇を差し掛けて渡廊下に連絡する。外部は押縁下見板張で，内部は弁護士控所や出頭人控所などとする。区裁判所の構成を知る上で貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006113"},{"id":"00006089","register_sub_id":"101","register_pk":"107074","name":"宇城市国際交流村法の館（旧三角簡易裁判所本館）","kana":"うきしこくさいこうりゅうむらほうのやかた（きゅうみすみかんいさいばんしょほんかん）","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県宇城市三角町三角浦1031","lat":32.6232976,"lng":130.45663226,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積288㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"43 － 0087","desc":"港を一望する高台に位置し，東を正面とし，中央に起り破風の車寄を突き出す。寄棟造，桟瓦葺の木造平屋建で，東北隅に法廷を配する。外観は真壁造で，腰縦羽目，上部下見板張，小壁白漆喰塗とする。司法省営繕による和風色の強い地方裁判所庁舎建築の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006089"},{"id":"00006088","register_sub_id":"101","register_pk":"107073","name":"九州海技学院正門及び石垣（旧宇土郡役所正門及び石垣）","kana":"きゅうしゅうかいぎがくいんせいもんおよびいしがき（きゅううどぐんやくしょせいもんおよびいしがき）","category":"官公庁舎","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県宇城市三角町三角浦1193","lat":32.62277571,"lng":130.45718386,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"正門 石造、間口5.0m、石垣 石造、延長32m","structure_material":"正門 石造","registered":"2007.05.15(平成19.05.15)","register_no":"43 － 0091","desc":"本館の北方に東西棟で建ち，庁舎とは渡廊下で結ばれる。桁行７間半，梁間２間，寄棟造，桟瓦葺の木造平屋建で，南面に土庇を差し掛けて渡廊下に連絡する。外部は押縁下見板張で，内部は弁護士控所や出頭人控所などとする。区裁判所の構成を知る上で貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006088"},{"id":"00006082","register_sub_id":"101","register_pk":"107067","name":"九州海技学院本館（旧宇土郡役所庁舎）","kana":"きゅうしゅうかいぎがくいんほんかん（きゅううどぐんやくしょちょうしゃ）","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県宇城市三角町三角浦1193","lat":32.62270739,"lng":130.45740861,"geo_status":"db","era":"明治35／昭和63改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積260㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"43 － 0090","desc":"三角西港を見下ろす高台に建つ。寄棟造，桟瓦葺，木造平屋建の洋風庁舎で，モルタル塗外壁に目地を切って石造風に見せる。両翼を張り出した形態とし，中央にスティックスタイルの車寄を付け，屋根にドーマー窓を載せる。明治中期熊本県営繕の力量を示す作品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006082"},{"id":"00011225","register_sub_id":"101","register_pk":"205332","name":"旧御船区裁判所庁舎","kana":"きゅうみふねくさいばんしょちょうしゃ","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県上益城郡御船町大字御船字町園又851-7-2","lat":32.70769,"lng":130.799765,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積322㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"43 - 0156","desc":"県下に九箇所置かれていた区裁判所庁舎。後に御船簡易裁判所となり、昭和四六年の移転まで用いられた。寄棟造桟瓦葺で、正面中央に起り屋根の玄関を設ける。内部は中廊下を矩折に通し、法廷や検事の執務室等を配していた。数少ない地方の裁判所庁舎建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011225"},{"id":"00011226","register_sub_id":"101","register_pk":"205333","name":"旧御船区裁判所門柱及び塀","kana":"きゅうみふねくさいばんしょもんちゅうおよびへい","category":"官公庁舎","subcategory":"その他工作物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県上益城郡御船町大字御船字町園又851-7-2","lat":32.7079188,"lng":130.79977184,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 鉄筋コンクリート造、間口3.6m 塀 石造、延長6.0m","structure_material":"門 鉄筋コンクリート造","registered":"2016.08.01(平成28.08.01)","register_no":"43 - 0157","desc":"敷地正面側を画する門及び塀。門の東側に矩折に延びる石塀が残る。門柱は高さ二・四メートルで、基礎部と柱身に繰型を施し柱頭は放物線状に仕上げるなど、表現主義的な要素がみられる。塀は切石六段積とし、頂部に笠石を乗せている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011226"},{"id":"00003771","register_sub_id":"101","register_pk":"104761","name":"旧山江村役場庁舎","kana":"きゅうやまえむらやくばちょうしゃ","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県球磨郡山江村大字山田甲1415","lat":32.24901746,"lng":130.76837627,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積233㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"43 － 0058","desc":"木造総２階建，切妻造，桟瓦葺，平入で，正面中央を少し突出させて１階に切妻造の玄関を設ける。もとは１階が執務室，２階が議会議場。外壁は１階下見板張，２階モルタル塗とし，正面突出部と両側面では柱を現して意匠を引き立てる。地域のシンボル的な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003771"},{"id":"00006294","register_sub_id":"101","register_pk":"107277","name":"相良村ふるさと館（旧四浦村役場庁舎）","kana":"さがらむらふるさとかん（きゅうしうらむらやくばちょうしゃ）","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県球磨郡相良村大字深水2136","lat":32.2401859,"lng":130.79848548,"geo_status":"db","era":"昭和17／平成12移築","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造2階建、瓦葺、建築面積171㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"43 － 0092","desc":"村の温泉施設の北方に位置し，東面して建つ。桁行１６ｍ，梁間１１ｍの規模で，木造２階建，寄棟造，桟瓦葺とする。１階は事務室として使用され，南側及び西側に階段を設け，２階は１室の会議室とする。窓面積を大きくとり，地方の旧庁舎の外観を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006294"},{"id":"00000178","register_sub_id":"101","register_pk":"101168","name":"旧緒方村役場","kana":"きゅうおがたむらやくば","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県豊後大野市緒方町馬場字柏木574","lat":32.97143051,"lng":131.47811304,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建，瓦葺，建築面積302㎡","structure_material":"木造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"44 － 0005","desc":"小高い丘の上に建つ木造２階建の旧村役場で，今も町民に親しまれている建物である。洋風を基調とする構造や意匠をもち，全体として素朴な外観になるが，正面玄関部分はスクラッチタイルを用い，２階上部には丸型の小屋根を張り出すなど装飾を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000178"},{"id":"00012665","register_sub_id":"101","register_pk":"367959","name":"旧豊予要塞司令官官舎","kana":"きゅうほうよようさいしれいかんかんしゃ","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県大分市大字佐賀関字太田180-2","lat":33.253567,"lng":131.884079,"geo_status":"geocoded","era":"大正15年頃／平成29年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、180㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"44 － 0230","desc":"佐賀関の要塞司令部跡の裏山中腹に東面して建つ。切妻造桟瓦葺の平屋建で、正面北端にコンクリート造風の玄関付洋館を設け、背面に別棟を延ばす。玄関の北に応接間、南に次の間と座敷を設け、別棟を居住空間とする。旧陸軍の仕様を示す和洋館併設の官舎建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012665"},{"id":"00000609","register_sub_id":"101","register_pk":"101599","name":"別府市児童館（旧別府郵便電話局電話分室）","kana":"べっぷしじどうかん（きゅうべっぷゆうびんでんわきょくでんわぶんしつ）","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県別府市末広町1-3","lat":33.27442274,"lng":131.50276735,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造２階建，建築面積649㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1998.07.23(平成10.07.23)","register_no":"44 － 0039","desc":"鉄筋コンクリート造，煉瓦タイル貼になるコの字型の建物で，全体に装飾的要素を極力抑えたシンプルな構成になる。設計は旧別府市公会堂と同じく逓信省技師吉田鉄郎で，近代合理主義を追求した吉田の過渡期の作品の一つに数えられる。施工は，金子仙吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000609"},{"id":"00010406","register_sub_id":"101","register_pk":"199178","name":"旧田原村役場","kana":"きゅうたばるそんやくば","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県西臼杵郡高千穂町大字河内字中河内36-1","lat":32.77684,"lng":131.254943,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積159㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"45-0081","desc":"高千穂往還の要諦となる斜面地に東面して建つ。木造二階建、下見板張で、屋根を半切妻とし洋風外観とする。一階は村長室と事務室、二階は議場等を配する。階段等の細部に幾何模様を施す一方、玄関ポーチでは社寺風の組物で軒を支えるなど、和洋の意匠に富む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010406"},{"id":"00014126","register_sub_id":"101","register_pk":"508386","name":"旧宮崎農工銀行（宮崎県庁５号館）","kana":"きゅうみやざきのうこうぎんこう（みやざきけんちょうごごうかん）","category":"官公庁舎","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"宮崎県","address":"宮崎県宮崎市橘通東一丁目44","lat":31.90972778,"lng":131.42372778,"geo_status":"db","era":"昭和元年／令和2年移築","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積406㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"45 - 0112","desc":"県庁防災広場に建つ旧宮崎農工銀行社屋。鉄筋コンクリート造二階建、正面にバルコニーを張出し、中層をタイル張とする。内部は吹抜にギャラリーを廻し、円柱はイオニア式の柱頭を飾る。細部には幾何学形態を導入して明朗な意匠をもつ。端正な意匠の銀行建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014126"},{"id":"00011606","register_sub_id":"101","register_pk":"210525","name":"宮崎県庁舎正門門柱","kana":"みやざきけんちょうしゃせいもんもんちゅう","category":"官公庁舎","subcategory":"その他工作物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県宮崎市橘通東二丁目35","lat":31.91039111,"lng":131.42388306,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造、間口8.1m、東西脇柱付","structure_material":"鉄筋コンクリート造","registered":"2017.05.02(平成29.05.02)","register_no":"45-0087","desc":"敷地の南辺に開き、庭を挟んで本館正面に至る。間口八・一メートルで、高さ三・二メートルの主柱と高さ二・四メートルの脇柱から成る。鉄筋コンクリート造で石張仕上げ。主柱は八角形で柱頭は本館パラペットと統一された小塔状の意匠で風格ある表構えである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011606"},{"id":"00011607","register_sub_id":"101","register_pk":"210526","name":"宮崎県庁舎東門門柱","kana":"みやざきけんちょうしゃひがしもんもんちゅう","category":"官公庁舎","subcategory":"その他工作物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県宮崎市橘通東二丁目35","lat":31.91104806,"lng":131.42439389,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造、間口5.4m、北方脇柱付","structure_material":"鉄筋コンクリート造","registered":"2017.05.02(平成29.05.02)","register_no":"45-0088","desc":"本館東側の通りに面して立つ。間口五・四メートルで、高さ二・一メートルの主柱と高さ一・八メートルの右門脇柱から成る。鉄筋コンクリート造で石張仕上げ。柱は共に四角形で、柱頭は本館パラペットの小塔状の意匠を意識したもので、敷地東面の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011607"},{"id":"00011605","register_sub_id":"101","register_pk":"210524","name":"宮崎県庁舎本館","kana":"みやざきけんちょうしゃほんかん","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県宮崎市橘通東二丁目35","lat":31.91104306,"lng":131.42389694,"geo_status":"db","era":"昭和7年／昭和37年・同46年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積2537㎡、塔屋及び煙突付","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2017.05.02(平成29.05.02)","register_no":"45-0086","desc":"鉄筋コンクリート造三階地下一階建で、塔屋と煙突が付く。日の字型平面の中央に旧議事堂を配し、南正面に車寄玄関を開く。正面三階中央に正庁、その脇に貴賓室を置く。ネオゴシックを基調とした垂直性の強い堂々たる外観を見せ、県都を代表する建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011605"},{"id":"00001025","register_sub_id":"101","register_pk":"102015","name":"鹿児島市庁舎本館","kana":"かごしましちょうしゃほんかん","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県鹿児島市山下町11-1","lat":31.59688358,"lng":130.55702871,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造３階建，建築面積2813㎡","structure_material":"鉄筋コンクリート造３階建","registered":"1998.12.11(平成10.12.11)","register_no":"46 － 0002","desc":"大蔵省営繕管財局の設計になる府県庁舎スタイルを踏襲した市庁舎建築であるが，当時の岩元市長の強い意向により，ベースメント層を設けずに道路からストレートに入れるようなプランニングをとっている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001025"},{"id":"00007146","register_sub_id":"101","register_pk":"108128","name":"旧鹿児島県庁舎正面門","kana":"きゅうかごしまけんちょうしゃしょうめんもん","category":"官公庁舎","subcategory":"その他工作物","type_guess":"庁舎","type_guess_confidence":"high","period":"大正","pref":"鹿児島県","address":"鹿児島県鹿児島市山下町14-1","lat":31.59909379,"lng":130.55837683,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"石造門柱2基、間口4.0m、両側通用門付","structure_material":"石造門柱2基","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0063","desc":"間口４．０ｍ、高さ２．５ｍ規模の本柱の東北と西南に高さ２．８ｍの脇柱を配する。ともに花崗石製で、台座・柱身・笠石の３層構成をとり、本柱頂部には照明器具、脇柱頂部にはカップ状の飾りを配する。旧鹿児島県庁舎の正面を画した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007146"},{"id":"00006084","register_sub_id":"101","register_pk":"107069","name":"旧勝目郵便局","kana":"きゅうかつめゆうびんきょく","category":"官公庁舎","subcategory":"建築物","type_guess":"郵便局","type_guess_confidence":"high","period":"昭和前","pref":"鹿児島県","address":"鹿児島県南九州市川辺町中山田1134-3","lat":31.36974909,"lng":130.35480845,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"46 － 0036","desc":"街道に西面して南北棟で建つ。桁行６間，梁間５間半，半切妻造，桟瓦葺の木造平屋建で，正面中央の玄関上部にも半切妻の破風を見せる。外壁は下見板張とし，窓枠材を伸ばしてスティックスタイル風の外観をつくる。玄関庇の持送り金具に〒のマークを組み込む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006084"},{"id":"00007145","register_sub_id":"101","register_pk":"108127","name":"県政記念館（旧鹿児島県庁舎本館）","kana":"けんせいきねんかん（きゅうかごしまけんちょうしゃほんかん）","category":"官公庁舎","subcategory":"建築物","type_guess":"庁舎","type_guess_confidence":"high","period":"大正","pref":"鹿児島県","address":"鹿児島県鹿児島市山下町14-1","lat":31.5990351,"lng":130.55693404,"geo_status":"db","era":"大正14／平成12移築改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積334㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0062","desc":"曽禰中條建築事務所設計によるロの字型平面の県庁舎建築の正面玄関及び中央階段部分。大正期におけるネオ・ルネッサンス様式による県庁舎建築で、中央は３階建とし、玄関車寄のトスカナ式の双柱に２階のイオニア式の柱を重ね、威厳ある正面をつくりあげている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007145"},{"id":"00007705","register_sub_id":"101","register_pk":"108687","name":"重富小学校正門（旧鹿児島県庁正門）","kana":"しげとみしょうがっこうせいもん（きゅうかごしまけんちょうせいもん）","category":"官公庁舎","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県姶良市平松5636","lat":31.7063194,"lng":130.60453374,"geo_status":"db","era":"明治13／大正15移築","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"石造門柱4基、間口7.2m","structure_material":"石造門柱4基","registered":"2009.04.28(平成21.04.28)","register_no":"46 － 0080","desc":"校地の北辺中央に位置する。西南戦争後建設の第２期鹿児島県庁舎の正門。間口７．２ｍの洋風石造門で、柱間３．７ｍに高さ３．８ｍの本柱をたてる。脇柱は高さ３．１ｍ。花崗岩を江戸切り仕上げとし、頂部にフィニアルを付ける。校門として地域に親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007705"},{"id":"00002188","register_sub_id":"101","register_pk":"103178","name":"旧西岡水源池取水塔","kana":"きゅうにしおかすいげんちしゅすいとう","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道札幌市豊平区西岡公園内","lat":42.98645324,"lng":141.3801849,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"煉瓦及び木造、鉄板葺、建築面積1.5㎡","structure_material":"煉瓦及び木造","registered":"2001.08.28(平成13.08.28)","register_no":"01 － 0029","desc":"旧陸軍第７師団歩兵第２５連隊用として月寒川上流部に建設された水道施設。内径１．５m，高６．６mの円柱状煉瓦造基礎上に，六角形平面，下見板張，縦長窓付の木造胴体部と，六角錐形の屋根が載る。井上二郎設計。公園のシンボルとして市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002188"},{"id":"00007825","register_sub_id":"101","register_pk":"108806","name":"旧島守発電所水圧鉄管路","kana":"きゅうしまもりはつでんしょすいあつてっかんろ","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"青森県","address":"青森県八戸市南郷区大字島守字持金沢3","lat":40.39681487,"lng":141.48005228,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"鋼製、延長21m、土台付","structure_material":"鋼製","registered":"2009.11.02(平成21.11.02)","register_no":"02-0081","desc":"本館と水槽間に据えられた水圧鉄管路。法勾配２割２分の斜面に据えられ、下端で水平方向に屈曲する延長２１ｍ、外径１．４ｍの円筒形鉄管とコンクリート造の受台からなる。県内に現存する最古の水力発電所施設の遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007825"},{"id":"00007824","register_sub_id":"101","register_pk":"108805","name":"旧島守発電所水槽","kana":"きゅうしまもりはつでんしょすいそう","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"青森県","address":"青森県八戸市南郷区大字島守字持金沢3","lat":40.39666363,"lng":141.48020332,"geo_status":"db","era":"大正3／昭和30増設・昭和48改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"コンクリート造、面積190㎡","structure_material":"コンクリート造","registered":"2009.11.02(平成21.11.02)","register_no":"02-0080","desc":"本館から１６ｍ東方の高台に位置する。水車に流入する水量の調整等を行うために導水路と水圧管の接合点に築かれた、延長３３ｍ、「く」の字形平面のコンクリート構造物で、表面モルタル塗仕上げとする。余水路に接続するごみ捨路を一体化した特徴的なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007824"},{"id":"00007823","register_sub_id":"101","register_pk":"108804","name":"旧島守発電所本館","kana":"きゅうしまもりはつでんしょほんかん","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"青森県","address":"青森県八戸市南郷区大字島守字持金沢3","lat":40.39691158,"lng":141.47999629,"geo_status":"db","era":"大正3／昭和30改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"02-0079","desc":"市内を南北に貫流する新井田川の上流域に位置する。川に面する敷地に建つ桁行１３ｍ梁間７．６ｍ、切妻造妻入の木造平屋建。外装下見板張とし、縦長上下窓を配し、南妻面にはポーチを付ける。ドイツ製の横軸水車と発電機を一組残す近代水力発電所施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007823"},{"id":"00007826","register_sub_id":"101","register_pk":"108807","name":"旧島守発電所余水路","kana":"きゅうしまもりはつでんしょよすいろ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"青森県","address":"青森県八戸市南郷区大字島守字持金沢3","lat":40.3969338,"lng":141.48016482,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"コンクリート造、延長53m","structure_material":"コンクリート造","registered":"2009.11.02(平成21.11.02)","register_no":"02-0082","desc":"水槽より北側に位置し、新井田川に合流する水路。余水や土砂等を川に流し出すために築かれた延長５３ｍ、台形断面とする直線状のコンクリート造構造物で、全体のうち２１ｍは暗渠とする。水力発電所施設のシステムを知る上で欠くことのできない構造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007826"},{"id":"00001217","register_sub_id":"101","register_pk":"102207","name":"米内浄水場１号ろ過池調整室","kana":"よないじょうすいじょういちごうろかちちょうせいしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県盛岡市上米内字中居49","lat":39.74487702,"lng":141.20254604,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造，建築面積10㎡","structure_material":"鉄筋コンクリート造","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0015","desc":"東寄りの１号濾過池に対応するバルブ操作室上屋。正方形プランのＲＣ造モルタル塗の小建築であるが、土台回り、腰回り、開口部回り、コーナーストーン、軒の持送りなど要所に大谷石を用いて装飾効果を高めている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001217"},{"id":"00001214","register_sub_id":"101","register_pk":"102204","name":"米内浄水場緩速系着水井","kana":"よないじょうすいじょうかんそくけいちゃくすいせい","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県盛岡市上米内字中居49","lat":39.74509956,"lng":141.20325682,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造，面積17.１㎡","structure_material":"鉄筋コンクリート造","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0012","desc":"昭和９年に配水を開始した盛岡市創設水道の基幹施設になる米内浄水場の東端に位置する。９．５ｍ×１．８ｍ、深さ約２ｍのＲＣ造池で、内部を３室に区画する。約１ｋｍ上流で取水され沈砂池を経て導水された水はこの池に着水し、量水の後、沈殿池に送られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001214"},{"id":"00001215","register_sub_id":"101","register_pk":"102205","name":"米内浄水場緩速沈殿池","kana":"よないじょうすいじょうかんそくちんでんち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県盛岡市上米内字中居49","lat":39.74546956,"lng":141.20297691,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造，１号・２号沈殿池よりなる，面積1458㎡","structure_material":"鉄筋コンクリート造","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0013","desc":"構内東方の一段高い造成地に着水井とともに築造され、着水井の北方に隣接して配置されている。５４ｍ×２７ｍ、有効水深３ｍのＲＣ造池で、中央に隔壁を設けて２池とする。各池は正方形平面で、側壁の内側に煉瓦を貼り、上部に笠石を置く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001215"},{"id":"00001216","register_sub_id":"101","register_pk":"102206","name":"米内浄水場緩速ろ過池","kana":"よないじょうすいじょうかんそくろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県盛岡市上米内字中居49","lat":39.745228,"lng":141.202515,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造，ろ過池面積3347㎡","structure_material":"鉄筋コンクリート造","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0014","desc":"沈殿池の南に位置する。９０ｍ×３７ｍの矩形平面のＲＣ造池で、２つの隔壁により３池に等分し、１池を予備池とする。濾材として砂と砂利を敷き、側壁の内側は沈殿池と同様に煉瓦貼りとし、各池の南辺中央に調整室を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001216"},{"id":"00001219","register_sub_id":"101","register_pk":"102209","name":"米内浄水場３号ろ過池調整室","kana":"よないじょうすいじょうさんごうろかちちょうせいしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県盛岡市上米内字中居49","lat":39.74531202,"lng":141.20212422,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造，建築面積10㎡","structure_material":"鉄筋コンクリート造","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0017","desc":"米内川に沿った構内敷地西辺寄りに位置する３号濾過池に対応するバルブ操作室上屋。１号・２号濾過池調整室と同規模、同意匠、同仕様の建屋で、ＪＲ山田線上米内駅に向き合う正門を入って右手に拡がる浄水場景観のアイストップ的な役割を果たしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001219"},{"id":"00001220","register_sub_id":"101","register_pk":"102210","name":"米内浄水場出水井","kana":"よないじょうすいじょうしゅっすいせい","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県盛岡市上米内字中居49","lat":39.744568,"lng":141.202515,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造，建築面積15㎡","structure_material":"鉄筋コンクリート造","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0018","desc":"正門を入って左手に建つ。八角形平面の建屋で、平屋建であるが、外観上は二層構成とし、上層に濾過池調整室と同系統意匠の丸窓を配する。大谷石は、出隅部のバットレスとバンドコースに用いて、調整室とは変化をもたせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001220"},{"id":"00001221","register_sub_id":"101","register_pk":"102211","name":"米内浄水場水道記念館","kana":"よないじょうすいじょうすいどうきねんかん","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県盛岡市上米内字中居49","lat":39.74454409,"lng":141.20219167,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積157㎡","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0019","desc":"敷地南東寄り、沈殿池・濾過池など構内を見渡せる位置に建つ。創設時の管理事務所で、正面左右に翼屋を張出す凹字型プランをとる。木造平屋建、瓦葺寄棟屋根の正面中央にドーマー窓を載せる。スクラッチタイルの使用に時代的な特徴が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001221"},{"id":"00001218","register_sub_id":"101","register_pk":"102208","name":"米内浄水場２号ろ過池調整室","kana":"よないじょうすいじょうにごうろかちちょうせいしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県盛岡市上米内字中居49","lat":39.74509684,"lng":141.20232349,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造，建築面積10㎡","structure_material":"鉄筋コンクリート造","registered":"1999.08.23(平成11.08.23)","register_no":"03 － 0016","desc":"濾過池の中央に位置する２号濾過池に対応するバルブ操作室上屋。１号濾過池調整室と同規模、同意匠、同仕様で、濾過池南辺の中央部に建つ。大谷石で縁取られた丸窓と小丸換気孔、半円ヴォールト屋根を重ねた濾過池側の立面は水辺に佇む小宮殿風の趣を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001218"},{"id":"00001088","register_sub_id":"101","register_pk":"102078","name":"青下隧道入口","kana":"あおしたずいどういりぐち","category":"生活関連","subcategory":"土木構造物","type_guess":"隧道","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区大倉字大原新田12-7地先","lat":38.29831477,"lng":140.69475921,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"玉石張鉄筋コンクリート造，幅6.0m，高さ3.9m","structure_material":"玉石張鉄筋コンクリート造","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0015","desc":"青下第１ダム下流側左岸に設けられた量水池より中原浄水場へ向かう延長６９６ｍの導水隧道の上口。隧道坑門は、坑口両脇の柱型やコーニス部のマチコレーション飾りにより仕上げられた丁寧な造りの石造ポータルで、坑口アーチ上部に扁額を掲げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001088"},{"id":"00001086","register_sub_id":"101","register_pk":"102076","name":"青下第１ダム","kana":"あおしただいいちだむ","category":"生活関連","subcategory":"土木構造物","type_guess":"堰堤","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区熊ヶ根字大原道17-2地先","lat":38.29840859,"lng":140.69460021,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"コンクリート造堰堤，玉石張，副堰堤及び青下橋附属，主堰堤堤高13.4m，堤長41.8m，副堰堤堤高2.4m，堤長25.7m，青下橋長さ43.6m，幅員1.8m","structure_material":"コンクリート造堰堤","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0013","desc":"仙台市水道第一次拡張時の取水ダムで、広瀬川支流の青下川に設けられた三つのダムの内最下流のもの。堤長４１．５ｍ、堤高１３ｍの玉石コンクリート造玉石貼の越流式重力ダムで、下流側に副ダムを設け、主ダム頂上に管理用の桁橋（青下橋）を付設する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001086"},{"id":"00001087","register_sub_id":"101","register_pk":"102077","name":"青下第１ダム取水塔","kana":"あおしただいいちだむしゅすいとう","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区熊ヶ根字大原道17-2地先","lat":38.29845712,"lng":140.69476098,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造，高さ15.5m","structure_material":"鉄筋コンクリート造","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0014","desc":"第１ダム上流側左岸寄りに設置された独立塔状の鉄筋コンクリート造取水塔で、内径２．４ｍ、高さ１６．９７ｍの規模を有し、塔頂部において管理橋（青下橋）に連絡する。上中下三段の取水管より取水し、主ダム下流側左岸の量水池に導水する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001087"},{"id":"00001090","register_sub_id":"101","register_pk":"102080","name":"青下第３ダム","kana":"あおしただいさんだむ","category":"生活関連","subcategory":"土木構造物","type_guess":"堰堤","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区大倉字前原1-2地先","lat":38.30816745,"lng":140.69101235,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"コンクリート造堰堤，玉石張，副堰堤及び管理橋附属，主堰堤堤高15.2m，堤長60.4m，副堰堤堤高2.4m，堤長27.7m，管理橋長さ15.5m，幅員1.2m","structure_material":"コンクリート造堰堤","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0017","desc":"青下第２ダムの上流に位置する。堤長６０．４ｍ、堤高１５．１５ｍ、第２貯水池との満水位差は約１８ｍ。第２ダムと同様の玉石コンクリート造玉石貼の管理橋付き越流式重力ダムであるが、泥吐出口を副ダム下流部に設けているのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001090"},{"id":"00001089","register_sub_id":"101","register_pk":"102079","name":"青下第２ダム","kana":"あおしただいにだむ","category":"生活関連","subcategory":"土木構造物","type_guess":"堰堤","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区熊ヶ根字大原道27-2地先","lat":38.30103695,"lng":140.68136393,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"コンクリート造堰堤，玉石張，副堰堤及び管理橋附属，主堰堤堤高14.4m，堤長39.2m，副堰堤堤高2.4m，堤長23.6m，管理橋長さ23.6m，幅員1.5m","structure_material":"コンクリート造堰堤","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0016","desc":"青下第１ダムの上流に位置し、堤長３９．２ｍ、堤高１６．２８ｍの規模をもつ。第１貯水池との満水位差は約１０ｍ。第１ダムと同様の玉石コンクリート造玉石貼の越流式重力ダムで、下流部に副ダムを付設する。主ダム頂部右岸側には長１４ｍの管理橋を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001089"},{"id":"00001093","register_sub_id":"101","register_pk":"102083","name":"青下ダム記念碑","kana":"あおしただむきねんひ","category":"生活関連","subcategory":"その他工作物","type_guess":"堰堤","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区熊ヶ根字大原道18地先","lat":38.30012313,"lng":140.69339854,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"石造，幅14.4m，奥行6.9m，高さ2.6m","structure_material":"石造","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0020","desc":"青下第１ダム右岸に至る取付通路脇の平地に設置された記念碑。地元産の石材を用い、正面に山羊頭の噴水口を設け、背面に「仙台市水道拡張工事誌」銘板を填め込む。銘板には、顧問の茂庭忠次郎、技術部長の八島明、技師の杉本宗二郎らの名が記されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001093"},{"id":"00001092","register_sub_id":"101","register_pk":"102082","name":"青下ダム旧管理事務所","kana":"あおしただむきゅうかんりじむしょ","category":"生活関連","subcategory":"建築物","type_guess":"堰堤","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区熊ヶ根字大原道18地先","lat":38.29927312,"lng":140.69485199,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造平屋建一部２階建，建築面積70㎡","structure_material":"鉄筋コンクリート造平屋建一部２階建","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0019","desc":"青下第１貯水池右岸に水源地事務所として建てられたもの。階段室を曲面状に突出させた国際様式志向の建築で、丸窓の意匠も時代性を物語る。水道拡張課建築係長鹿井清吾のもとで、菊地孝太郎（ともに仙台市工出身）が担当したと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001092"},{"id":"00001091","register_sub_id":"101","register_pk":"102081","name":"青下量水堰","kana":"あおしたりょうすいぜき","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区大倉字西原38地先","lat":38.31268141,"lng":140.68534358,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"コンクリート造堰堤，玉石張，堤高2.0m，堤長20.0m","structure_material":"コンクリート造堰堤","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0018","desc":"青下第３ダムの上流５１８ｍの地点に位置する堤長２０ｍ、堤高２ｍ、敷幅３．４ｍ堤頂幅０．６ｍの玉石コンクリート造玉石貼の小ダム。右岸近くに幅１．３７ｍ、深さ０．５ｍの切欠きを設けて常時の流水量を計量する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001091"},{"id":"00001097","register_sub_id":"101","register_pk":"102087","name":"荒巻配水池入口","kana":"あらまきはいすいちいりぐち","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区国見3-6-1地先","lat":38.27217625,"lng":140.84122971,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄筋コンクリート造，幅4.5m，高さ2.7m","structure_material":"鉄筋コンクリート造","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0024","desc":"仙台市水道創設時における配水池の中央監視廊出入口。コンクリートブロックで造られる。配水所正門の正面に位置し、市内配水の起点に当たるため、出入口のアーチとムクリアーチ状の笠石との間を葉状の浮彫で飾るなど装飾的な造りとなっているのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001097"},{"id":"00016475","register_sub_id":"101","register_pk":"574837","name":"旧石巻市大街道浄水場事務所","kana":"きゅういしのまきしおおかいどうじょうすいじょうじむしょ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県石巻市尾崎字鍜治間10","lat":38.54928889,"lng":141.47053333,"geo_status":"db","era":"昭和5年頃／昭和54年改修、令和6年移築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"04 - 0244","desc":"長面浦沿岸の敷地に移築された旧大街道浄水場の事務所。木造平屋建腰折屋根のスレート葺で、南面に切妻造の玄関ポーチを設け、北面に附属屋を延ばす。外壁は下見板とする。内部は中廊下の左右に板敷の部屋を配す。地域の水道施設の歴史を伝える貴重な事務所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016475"},{"id":"00001233","register_sub_id":"101","register_pk":"102223","name":"三居沢発電所","kana":"さんきょざわはつでんじょ","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県仙台市青葉区荒巻字三居沢17-1","lat":38.266979,"lng":140.840271,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建，鋼板葺，建築面積169㎡","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"04 － 0025","desc":"東北地方最初の発電所の二代目建屋。木造平屋建、下見板貼のほぼ正方形プランの建屋で、寄棟屋根の中央部を一段高く上げて切妻屋根を架け、平の面を前面明かり取り窓とする特徴的な外観を呈す。棟札より棟梁伊藤今朝五郎、脇棟梁伊藤利三郎が判明している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001233"},{"id":"00001094","register_sub_id":"101","register_pk":"102084","name":"中原系苦地取水口","kana":"なかはらけいくちしゅすいこう","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区芋沢字中田西29-1地先","lat":38.30454597,"lng":140.70584562,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"鉄筋コンクリート造，高さ8.5m","structure_material":"鉄筋コンクリート造","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0021","desc":"広瀬川の支流大倉川左岸に設けられた仙台市創設水道の取水口で、中原浄水場へ導水する。取水口は煉瓦造で造られ、煉瓦アーチと煉瓦柱型によりポータルが構成され、両翼を玉石貼コンクリート造とする。仙台市創設水道のモニュメントとして貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001094"},{"id":"00001095","register_sub_id":"101","register_pk":"102085","name":"中原浄水場旧管理事務所","kana":"なかはらじょうすいじょうきゅうかんりじむしょ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区芋沢字中原24地先","lat":38.28293083,"lng":140.7541194,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造平屋建，建築面積74㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"04 － 0022","desc":"創設時の浄水場事務所を第一次拡張時に鉄筋コンクリート造で建替えたもの。近年改装されて寄棟屋根が架けられ、外装も石目地風に改められたが、当初は陸屋根造でパラペットにスペイン瓦を載せたモダニズム色の強い建築であった。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001095"},{"id":"00005237","register_sub_id":"101","register_pk":"106225","name":"今福浄水場ポンプ室","kana":"いまふくじょうすいじょうぽんぷしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県足利市今福545","lat":36.33663287,"lng":139.42927989,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造地上1階地下1階建、建築面積208㎡","structure_material":"鉄筋コンクリート造地上1階地下1階建","registered":"2006.03.02(平成18.03.02)","register_no":"09 － 0132","desc":"渡良瀬川左岸に位置する水道施設。開口部を広くとる採光に配慮した造りで，１階を吹抜けとする。丸くおさめた出隅部分や窓形状等が特徴的。正面を曲面状に張出し，柱頭部を幾何学的モチーフで飾る円柱を配するなどゼツェッシオン風意匠も取り入れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005237"},{"id":"00005738","register_sub_id":"101","register_pk":"106726","name":"宇都宮市水道今市水系第六号接合井","kana":"うつのみやしすいどういまいちすいけいだいろくごうせつごうせい","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県宇都宮市上金井町635-3","lat":36.63809109,"lng":139.84926071,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"コンクリート造、面積17㎡、煉瓦造上屋付","structure_material":"コンクリート造","registered":"2006.10.18(平成18.10.18)","register_no":"09 － 0150","desc":"市北部に位置し，日光街道にほぼ平行して敷設された延長約２５ｋｍの送水管にかかる水圧を調節するための施設。深さ２．３ｍのコンクリート造構造物の上に，西洋城郭風意匠をあしらう八角形平面の煉瓦造上屋を建てる。宇都宮市近代化の水道施設遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005738"},{"id":"00005748","register_sub_id":"101","register_pk":"106736","name":"宇都宮市水道資料館（旧管理事務所）","kana":"うつのみやしすいどうしりょうかん（きゅうかんりじむしょ）","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県日光市瀬川1334-1","lat":36.72739,"lng":139.679642,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積88㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"09 － 0159","desc":"宇都宮市創設水道の浄水場事務所建築。日光街道杉並木に北面する浄水場の北東部に建つ。南西隅部の円形平面の塔と下見板張外壁の太い押縁が特徴ある外観をつくり，屋根窓を載せた急傾斜の半寄棟屋根と塔のベル形ドームにより周辺で際立つ存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005748"},{"id":"00005739","register_sub_id":"101","register_pk":"106727","name":"宇都宮市水道戸祭配水場配水池","kana":"うつのみやしすいどうとまつりはいすいじょうはいすいち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県宇都宮市中戸祭町2841-2","lat":36.58484584,"lng":139.87525043,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造及びコンクリート造、面積1910㎡","structure_material":"煉瓦造及びコンクリート造","registered":"2006.10.18(平成18.10.18)","register_no":"09 － 0151","desc":"市の中心部に位置する。コンクリート造の一辺３１ｍの正方形の２池を並列し，導水壁の上部に煉瓦５枚厚の連続欠円アーチで屋蓋をつくる。外壁はフランス積風の煉瓦貼とし，隅部と階段には花崗岩を用いる。宇都宮市近代化の水道施設遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005739"},{"id":"00005241","register_sub_id":"101","register_pk":"106229","name":"緑町配水場水道計量室","kana":"みどりちょうはいすいじょうすいどうけいりょうしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県足利市緑町1-3780","lat":36.3388384,"lng":139.4355508,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積4.0㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"09 － 0136","desc":"敷地の東北部に位置する，配水を計量するための施設。桁行２．５ｍ，梁間１．５ｍ規模の鉄筋コンクリート造平屋建で，四隅に配した柱形と軒蛇腹を段状に迫り出すのが特徴的。米元晋一指導のもと建設が進められた足利市創設水道施設の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005241"},{"id":"00005238","register_sub_id":"101","register_pk":"106226","name":"緑町配水場水道山記念館（旧事務所）","kana":"みどりちょうはいすいじょうすいどうやまきねんかん（きゅうじむしょ）","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県足利市緑町1-3780","lat":36.33909207,"lng":139.43527856,"geo_status":"db","era":"昭和5／昭和9増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積200㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"09 － 0133","desc":"敷地の東北隅に位置する。玄関脇の事務室の背後に応接室や貴賓室を雁行形に配する。フランス瓦を用いたハーフティンバー風の木造平屋建で，背面にはドーマー窓を設ける。外壁は腰部と上部で仕様の異なるモルタル塗洗出しとする。水道創設時の施設の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005238"},{"id":"00005240","register_sub_id":"101","register_pk":"106228","name":"緑町配水場接合井","kana":"みどりちょうはいすいじょうせつごうせい","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県足利市緑町1-3780","lat":36.33862355,"lng":139.43450289,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造、面積43㎡、塩素滅菌室付","structure_material":"鉄筋コンクリート造","registered":"2006.03.02(平成18.03.02)","register_no":"09 － 0135","desc":"今福浄水場より東方の高台に築かれた配水場の施設。敷地の西南隅に位置し，浄水場ポンプ室より配水池へ送る水を中継する。上屋は鉄筋コンクリート造で，半円アーチを四周に配し，東側に塩素滅菌室を接続する。足利市が創設した水道施設の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005240"},{"id":"00005239","register_sub_id":"101","register_pk":"106227","name":"緑町配水場配水池","kana":"みどりちょうはいすいじょうはいすいち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県足利市緑町1-3780","lat":36.338848,"lng":139.434814,"geo_status":"db","era":"昭和5／昭和30頃増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造、面積1607㎡、水位計室及び保守点検入口棟付","structure_material":"鉄筋コンクリート造","registered":"2006.03.02(平成18.03.02)","register_no":"09 － 0134","desc":"敷地の西側中央部に位置する。幅約６０ｍ，奥行約２７ｍの鉄筋コンクリート造構造物で，内部は３池に区切られる。６角平面の各隅に柱形をつくり，軒蛇腹より上部に目地付のパラペットを立ち上げた水位計室と保守・点検入口棟を，東側にほぼ左右対称に配する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005239"},{"id":"00000337","register_sub_id":"101","register_pk":"101327","name":"桐生市水道局高区配水池","kana":"きりゅうしすいどうきょくこうくはいすいち","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市堤町1-2816-11","lat":36.41735694,"lng":139.33154212,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造，幅21.6m，長さ24.2m","structure_material":"鉄筋コンクリート造","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0016","desc":"旧配水事務所の北に位置する。正面２１．６ｍ，側面２４．２ｍ，深４．５ｍで，形式・形状ともに，浄水場調整池・低区配水池と似る。桐生市の水道施設は，元宿浄水場，堤町の高区・低区等からなる昭和初期に建設された一連の施設が良好に残る点が珍しい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000337"},{"id":"00000339","register_sub_id":"101","register_pk":"101329","name":"桐生市水道局高区量水室","kana":"きりゅうしすいどうきょくこうくりょうすいしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市堤町1-2816-11","lat":36.41610992,"lng":139.33162088,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造，建築面積6.2㎡","structure_material":"鉄筋コンクリート造","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0018","desc":"高区配水池と低区配水池との間の低区配水池寄りに位置する鉄筋コンクリート造の小規模な建物。屋根や入口に円弧状の曲線を巧みに用いる意匠やスクラッチタイルを張った腰壁等に，時代の特徴がよく表れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000339"},{"id":"00000338","register_sub_id":"101","register_pk":"101328","name":"桐生市水道局低区配水池","kana":"きりゅうしすいどうきょくていくはいすいち","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市堤町1-2816-11","lat":36.41559467,"lng":139.33133419,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造，幅29.9m，長さ29.2m","structure_material":"鉄筋コンクリート造","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0017","desc":"高区配水池の南方に位置する。正面２９．９ｍ，側面２９．２ｍ，深４．５ｍである。元宿浄水場，堤町の高区・低区等からなる一連の施設の計画を手がけたのは，東京帝国大学の中島鋭治（大正期）・草間偉・沼田征矢（昭和期）である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000338"},{"id":"00000340","register_sub_id":"101","register_pk":"101330","name":"桐生市水道局低区量水室","kana":"きりゅうしすいどうきょくていくりょうすいしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市堤町1-2816-11","lat":36.41552221,"lng":139.33271796,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造，建築面積6.2㎡","structure_material":"鉄筋コンクリート造","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0019","desc":"低区配水池の東方にある一段低い場所に建つ鉄筋コンクリート造の小規模な建物で，規模・形態・意匠とも高区量水室と等しい。スクラッチタイルを用いる点は，元宿浄水場の諸施設や旧配水事務所と似るが，円弧状の曲線を用いる点に独自の特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000340"},{"id":"00000342","register_sub_id":"101","register_pk":"101332","name":"桐生市立西公民館機械室（旧水道倉庫）","kana":"きりゅうしりつにしこうみんかんきかいしつ（きゅうすいどうそうこ）","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県桐生市永楽町2-16","lat":36.41348056,"lng":139.33672695,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積60㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0021","desc":"旧事務所の北方に隣接して建つ倉庫で，現在は公民館の機械室として使われている。鉄筋コンクリート造で伝統的な土蔵造にみせかけている。時代の流行の先端をいく意匠を用いて建設されたものが多い桐生市の水道施設のなかでひときわ異彩をはなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000342"},{"id":"00000341","register_sub_id":"101","register_pk":"101331","name":"桐生市立西公民館本館（旧水道事務所）","kana":"きりゅうしりつにしこうみんかんほんかん（きゅうすいどうじむしょ）","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県桐生市永楽町2-16","lat":36.41329384,"lng":139.33667668,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造3階建，建築面積232㎡","structure_material":"鉄筋コンクリート造3階建","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0020","desc":"市街地西方に接道して建つ。建設当初は，鉄筋コンクリート造２階建で，３階は後の増築である。石張り風の目地があるモルタル壁，段差をつけた窓廻りの意匠，曲線を用いた開口部等に時代の特徴がよく表れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000341"},{"id":"00000331","register_sub_id":"101","register_pk":"101321","name":"水道資料館（元宿浄水場旧事務所）","kana":"すいどうしりょうかん（もとじゅくじょうすいじょうきゅうじむしょ）","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市元宿町14-37","lat":36.41153836,"lng":139.32565961,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造平屋建，建築面積122㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0010","desc":"桐生市の水道施設は，大正期に計画し，関東大震災の影響による一時延期の後，昭和になり再び調査を開始，昭和５年９月に工事に着手，７年４月に通水を開始している。旧事務所は浄水場敷地の東北隅に建ち，現在水道資料館と使用され広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000331"},{"id":"00000336","register_sub_id":"101","register_pk":"101326","name":"水道山記念館（旧配水事務所）","kana":"すいどうやまきねんかん（きゅうはいすいじむしょ）","category":"生活関連","subcategory":"建築物","type_guess":"記念碑","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市堤町1-5-7","lat":36.4168973,"lng":139.33138771,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建，建築面積157㎡","structure_material":"木造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0015","desc":"桐生市街の西方にある山裾に位置する。垂直線を強調した外観，外壁のスクラッチタイル等，意匠は浄水場の施設と似る。平面形式，木造タイル張りの構造，屋根のスペイン瓦等に独自の特徴がある。現在水道記念館として公開され，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000336"},{"id":"00003517","register_sub_id":"101","register_pk":"104507","name":"北甘変電所","kana":"ほっかんへんでんしょ","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県富岡市一ノ宮422","lat":36.25690734,"lng":138.86096914,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積156㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"10 － 0101","desc":"鉄筋コンクリート造，２階建で，ラーメン構造だが柱型を極力見せない平滑な外観とし，外壁モルタル塗は主要部をドイツ壁風仕上に塗り分ける。各部陸屋根に高低を付け，縦長窓，アーチ型小窓を多数配し，機能的な意匠を基調としながら変化に富んだ外観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003517"},{"id":"00000032","register_sub_id":"101","register_pk":"101022","name":"前橋市浄水場配水塔","kana":"まえばししじょうすいじょうはいすいとう","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県前橋市敷島町216","lat":36.41510508,"lng":139.0545378,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄骨造、高さ37.4m","structure_material":"鉄骨造","registered":"1996.12.20(平成8.12.20)","register_no":"10 － 0004","desc":"水道資料館に近接して建つ。給水塔は鉄骨造で，環状体の鉄筋コンクリート基礎に八本のラチス柱を立て水槽を支える構造になる。水槽は鋼鉄板製で，外側を断熱材で巻き更に銅板で覆っている。高さ３７．４ｍあり，地域のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000032"},{"id":"00000031","register_sub_id":"101","register_pk":"101021","name":"前橋市水道資料館（旧浄水構場事務所）","kana":"まえばししすいどうしりょうかん（きゅうじょうすいこうじょうじむしょ）","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県前橋市敷島町216","lat":36.41476545,"lng":139.05446661,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積183㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"10 － 0003","desc":"鉄筋コンクリート造２階建で，瓦葺の屋根と物見等の部分は，木造の小屋組となる。妻の片方を平面屋根とも半円形とし，２階窓枠や屋根の小窓を半円形とする特色ある外観は，広く親しまれている。平成元年度に内部を改修し，水道資料館として開館した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000031"},{"id":"00006665","register_sub_id":"101","register_pk":"107648","name":"前橋市中央児童遊園（るなぱあく）旧ラジオ塔","kana":"まえばししちゅうおうじどうゆうえん（るなぱあく）きゅうらじおとう","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県前橋市大手町3-16-3","lat":36.39522185,"lng":139.06350669,"geo_status":"db","era":"昭和8／昭和前期移設","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"コンクリート造一部石造、高さ4.9m","structure_material":"コンクリート造一部石造","registered":"2007.12.05(平成19.12.05)","register_no":"10 － 0247","desc":"前橋市中央児童遊園の北側中央に建つ。ラジオ放送の受信施設として日本放送協会前橋放送局開局に併せて建設された。花崗岩の基壇の上に、モルタル塗洗出し仕上げのコンクリート躯体を載せた、高さ４．９ｍの常夜灯風の構造物。わが国初期のラジオ放送関連施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006665"},{"id":"00000333","register_sub_id":"101","register_pk":"101323","name":"元宿浄水場急速濾過場","kana":"もとじゅくじょうすいじょうきゅうそくろかじょう","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市元宿町14-37","lat":36.41167619,"lng":139.32502037,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造平屋建，建築面積190㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0012","desc":"喞筒（ポンプ）場の西北に建つ。旧事務所・喞筒場と類似する意匠になるが，スクラッチタイルを用いない点が異なる。入口のある中央部に向かって順次高く前方に出る形にして，中央部を強調した左右対称のひときわ目立つ特異な外観に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000333"},{"id":"00000335","register_sub_id":"101","register_pk":"101325","name":"元宿浄水場接合井","kana":"もとじゅくじょうすいじょうせつごうせい","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市元宿町14-37","lat":36.4112532,"lng":139.32516533,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造，外径3.9m","structure_material":"鉄筋コンクリート造","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0014","desc":"喞筒場の南方に隣接して位置する。内径３．５ｍ，深１１．１ｍの大規模な井戸で，地上に円形の低い壁を立ち上げる。壁の仕上げを石造風の目地をつけたモルタル塗りとし，上部に石製の笠木を据える等，簡素ながら丁寧なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000335"},{"id":"00000334","register_sub_id":"101","register_pk":"101324","name":"元宿浄水場調整池","kana":"もとじゅくじょうすいじょうちょうせいち","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市元宿町14-37","lat":36.41129598,"lng":139.32536969,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造，幅15.2m，長さ21.1m","structure_material":"鉄筋コンクリート造","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0013","desc":"喞筒場の東にある。正面１５．２ｍ，側面２１．１ｍ，深さ３．０ｍで，東北隅に石造の階段があり，上部に換気口等を均等に配列する。旧事務所，喞筒場等と同時期に建設されたもので，桐生市の生活の近代化を示す施設のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000334"},{"id":"00000332","register_sub_id":"101","register_pk":"101322","name":"元宿浄水場喞筒室","kana":"もとじゅくじょうすいじょうぽんぷしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市元宿町14-37","lat":36.41141717,"lng":139.32521285,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造平屋建，建築面積280㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"10 － 0011","desc":"旧事務所の西南に建つ鉄筋コンクリート造，平屋建の施設。旧事務所と類似した意匠になる建物で，縦長の窓や柱形を使うことによって垂直線を強調した外観，外壁のスクラッチタイル，入口庇の装飾等に時代の特徴がよくあらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000332"},{"id":"00001901","register_sub_id":"101","register_pk":"102891","name":"児玉町旧配水塔","kana":"こだままちきゅうはいすいとう","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"埼玉県","address":"埼玉県本庄市児玉町児玉323-2","lat":36.18803255,"lng":139.13103139,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、高さ18m","structure_material":"鉄筋コンクリート造","registered":"2000.10.18(平成12.10.18)","register_no":"11 － 0025","desc":"昭和３～９年に行われた児玉町水道施設工事の一環で建設。ＲＣ造外装モルタル塗，高さ１７．５ｍの内部は揚水用ポンプ室と天井をドーム形にした筒形高架水槽からなり，入口と階段室が正面に突出する。現在は時報塔として利用。設計は県技手の宮原雄次郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001901"},{"id":"00005549","register_sub_id":"101","register_pk":"106537","name":"石岡第二発電所取水堰堤","kana":"いしおかだいにはつでんしょしゅすいえんてい","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県北茨城市中郷町石岡","lat":36.77679154,"lng":140.6805259,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長19m、堤高4.7m、取水制水門、排砂門及び一号開渠付","structure_material":"重力式コンクリート造堰堤","registered":"2006.08.03(平成18.08.03)","register_no":"08 － 0213","desc":"第一発電所本館より約１００ｍ東方に位置する水路式の水力発電所施設。堤長１９ｍ，堤高４．７ｍ規模の表面石積の重力式コンクリート造堰堤で，前面に石張の水叩を付ける。左岸には取水制水門を矩折れに配し，その背面に導水路の一部をなす開渠を連続させる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005549"},{"id":"00005552","register_sub_id":"101","register_pk":"106540","name":"石岡第二発電所水槽","kana":"いしおかだいにはつでんしょすいそう","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県北茨城市中郷町石岡","lat":36.7774316,"lng":140.68916203,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"鉄筋コンクリート造、面積64㎡","structure_material":"鉄筋コンクリート造","registered":"2006.08.03(平成18.08.03)","register_no":"08 － 0216","desc":"沈砂池の東側に接続する。長径１１ｍ，短径６ｍの楕円形平面を有する筒状の鉄筋コンクリート造構造物。頂部にスラブを架け，沈砂池との境には２門からなるストーニー式制水門を配する。南側にドレーンバルブ操作用の張出し部を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005552"},{"id":"00005550","register_sub_id":"101","register_pk":"106538","name":"石岡第二発電所沈砂池","kana":"いしおかだいにはつでんしょちんさち","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県北茨城市中郷町石岡","lat":36.77745045,"lng":140.6890052,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"鉄筋コンクリート造、面積337㎡、副水路付","structure_material":"鉄筋コンクリート造","registered":"2006.08.03(平成18.08.03)","register_no":"08 － 0214","desc":"取水堰堤の約７５０ｍ下流に位置する。長さ３０ｍ，幅９ｍのほぼ長方形平面をしたコンクリート造構造物で，表面をモルタル塗仕上げとする。山側に巡らされた副水路に排砂門を取り付け，副水路内の土砂の排出も可能とした周到なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005550"},{"id":"00005553","register_sub_id":"101","register_pk":"106541","name":"石岡第二発電所鉄管路擁壁","kana":"いしおかだいにはつでんしょてっかんろようへき","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県北茨城市中郷町石岡","lat":36.77721951,"lng":140.68945504,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"石造、延長49m","structure_material":"石造","registered":"2006.08.03(平成18.08.03)","register_no":"08 － 0217","desc":"水槽と本館を結ぶ１条の水圧鉄管に沿って築かれる。水槽下の鉄管取付部分の石積擁壁と，余水路及び道路の隣接部など補強が必要とされる箇所に，鉄管と平行に築かれた擁壁からなる。総延長４９ｍとし，花崗岩を用いた谷積で築かれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005553"},{"id":"00005554","register_sub_id":"101","register_pk":"106542","name":"石岡第二発電所本館","kana":"いしおかだいにはつでんしょほんかん","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県北茨城市中郷町石岡69-1","lat":36.77672245,"lng":140.68986033,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"鉄筋コンクリート造平屋建、鉄板葺、建築面積175㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"08 － 0218","desc":"大北川に面する敷地に，川と平行して建つ。桁行１８ｍ，梁間１０ｍ，切妻造で，小屋組はフィンクトラスとする。上部欠円アーチ形の大窓を平側に連続させリズム感のある立面とし，妻には特徴のある丸窓をあしらう。我が国初期の鉄筋コンクリート造建築物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005554"},{"id":"00005551","register_sub_id":"101","register_pk":"106539","name":"石岡第二発電所余水路","kana":"いしおかだいにはつでんしょよすいろ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県北茨城市中郷町石岡","lat":36.77727465,"lng":140.68923122,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"石造及びコンクリート造、延長107m","structure_material":"石造及びコンクリート造","registered":"2006.08.03(平成18.08.03)","register_no":"08 － 0215","desc":"沈砂池南側壁に沿って設けられた越流式余水吐から大北川に至る，延長１０７ｍの開渠。丘の斜面に築かれる。沈砂池及び副水路の土砂排出も行い，壁面は谷積で築いた石積とし，前面一部をコンクリートで補強したつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005551"},{"id":"00004316","register_sub_id":"101","register_pk":"105306","name":"小里川発電所取水所","kana":"おざとがわはつでんしょしゅすいじょ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市徳田町","lat":36.80242866,"lng":140.49615926,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長20m、堤高2.1m、取水口及び石積護岸74m付","structure_material":"重力式コンクリート造堰堤","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0146","desc":"小里川電力株式会社が計画した発電所施設の取水部分で，本館の約３ｋｍ上流に位置する。堤長２０ｍ，堤高２．１ｍの重力式コンクリート造堰堤を中心として，右岸側に魚道，左岸側に制水門と排砂門を配する。小規模ながら近代的要素を全体に備えた河川構造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004316"},{"id":"00004314","register_sub_id":"101","register_pk":"105304","name":"小里川発電所放水路","kana":"おざとがわはつでんしょほうすいろ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市徳田町","lat":36.78541097,"lng":140.48048423,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"コンクリート造、延長142m、鉄筋コンクリート造橋及び石積護岸17m付","structure_material":"コンクリート造","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0144","desc":"発電所本館から流れ出る水を里川まで導く水路。くの字形平面をした長１４２ｍの開渠で，敷幅を２．７ｍ，側壁法勾配３分の谷積とし，水路端部から連続して里川に石造護岸を築く。欠円アーチの上方側壁を布積石張とした鉄筋コンクリート造管理橋が３基架かる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004314"},{"id":"00004313","register_sub_id":"101","register_pk":"105303","name":"小里川発電所本館","kana":"おざとがわはつでんしょほんかん","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市徳田町1284-2","lat":36.78569321,"lng":140.48127534,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造平屋建、鉄板葺、建築面積186㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0143","desc":"里美村を南北に貫流する里川の上流域に位置する発電施設。鉄筋コンクリート造平屋建，切妻造，瓦棒鉄板葺で，平側中央部に玄関ポーチを設ける。小屋組は鉄骨フィンクトラスで，内部には横軸水車と発電機を据える。軒蛇腹を段状につくり，外観に変化をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004313"},{"id":"00004315","register_sub_id":"101","register_pk":"105305","name":"小里川発電所余水路","kana":"おざとがわはつでんしょよすいろ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市徳田町","lat":36.78743505,"lng":140.48154351,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"コンクリート造、延長281m、鉄筋コンクリート造橋付","structure_material":"コンクリート造","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0145","desc":"水槽からの余水を里川に導くための水路で，山の斜面の鉛直方向にほぼ一直線に穿たれる。３．６ｍ長の暗渠部分と，側壁を法勾配３分の谷積とした２７７ｍ長の開渠部分からなり，放水口近くにはスパン約１．５ｍの小規模な鉄筋コンクリート造橋を架ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004315"},{"id":"00004312","register_sub_id":"101","register_pk":"105302","name":"賀美発電所取水所","kana":"がみはつでんしょしゅすいじょ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市小菅町","lat":36.70188683,"lng":140.50920384,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長33m、堤高2.9m、沈砂地・取水口・導水路59m及び石積護岸99m付","structure_material":"重力式コンクリート造堰堤","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0142","desc":"茨城電気株式会社が計画した賀美発電所の取水部分で，本館から約４ｋｍ上流に位置する。堤長３３ｍ，堤高２．９ｍで堤頂部にむくりをつけた布積石張の重力式取水堰を中心に，丁寧な石材仕上が施された２門の制水門，コンクリート造沈砂池を一体的に築く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004312"},{"id":"00004311","register_sub_id":"101","register_pk":"105301","name":"賀美発電所放水路及び余水路","kana":"がみはつでんしょほうすいろおよびよすいろ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市上深荻町","lat":36.66526263,"lng":140.52010838,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"コンクリート造、延長299m、鉄筋コンクリート造橋付","structure_material":"コンクリート造","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0141","desc":"発電所本館東方の欠円アーチ型放水口から里川に至る放水路と，水槽から流れ出て放水路と合流する余水路からなる。水路側壁は法勾配約３分の谷積石張で精緻に築く。里川の近くに，側壁を布積石張とした欠円アーチの鉄筋コンクリート造管理橋を架ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004311"},{"id":"00004310","register_sub_id":"101","register_pk":"105300","name":"賀美発電所本館","kana":"がみはつでんしょほんかん","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市上深荻町320","lat":36.66548194,"lng":140.52033517,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積189㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0140","desc":"久慈川水系里川の中流域に建設された水力発電施設。木造平屋建，切妻造，瓦棒鉄板葺で，外装は下見板張とする。越屋根を設け，壁面に広く開口部をとる，換気に配慮したつくり。小屋組は木造プラットトラスで，発電機室には横軸水車と発電機を一組据える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004310"},{"id":"00001241","register_sub_id":"101","register_pk":"102231","name":"旧町屋変電所","kana":"きゅうまちやへんでんしょ","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県常陸太田市西河内下町1382-1","lat":36.6070416,"lng":140.53805405,"geo_status":"db","era":"明治42頃","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"煉瓦造平屋建，鉄板葺，建築面積191㎡","structure_material":"煉瓦造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"08 － 0014","desc":"明治４４年１月から旧太田町などに電気を供給した町屋発電所の変電施設。せいの高い切妻屋根、煉瓦造建屋の北側に棟を落とした寄棟屋根の建屋をつなげる姿形をとる。寄棟建屋部分の西面及び北面の一部を煉瓦壁で造る。県内初期発電関連施設の遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001241"},{"id":"00004320","register_sub_id":"101","register_pk":"105310","name":"徳田発電所取水所","kana":"とくだはつでんしょしゅすいじょ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市徳田町","lat":36.81420961,"lng":140.51284669,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長12m、堤高2.0m、取水口及び石積護岸138m付","structure_material":"重力式コンクリート造堰堤","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0150","desc":"徳田発電所本館から約２ｋｍ上流に位置する。堤長１２ｍ堤高２．０ｍの重力式コンクリート造堰堤の左端に排砂門と制水門を配し，暗渠で途中の沈砂池を経て発電所水槽に水を送る。小規模ながら，水路式水力発電の仕組みを知る上で欠くことのできない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004320"},{"id":"00004318","register_sub_id":"101","register_pk":"105308","name":"徳田発電所放水路","kana":"とくだはつでんしょほうすいろ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市徳田町","lat":36.79877585,"lng":140.49128801,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"コンクリート造、延長34m、鉄筋コンクリート造橋及び石積護岸33m付","structure_material":"コンクリート造","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0148","desc":"発電所本館下方の南西面から発する放水を里川左岸に導くための水路。３４ｍ長の開渠で，敷幅２．４ｍ，側壁を法勾配３分の谷積とし，里川に面して３３ｍ長の石積護岸を一体的に築く。水路に架かる鉄筋コンクリート造橋を含め，優れた石積技術を確認できる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004318"},{"id":"00004317","register_sub_id":"101","register_pk":"105307","name":"徳田発電所本館","kana":"とくだはつでんしょほんかん","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市徳田町","lat":36.80239684,"lng":140.49624182,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積81㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0147","desc":"里川水系発電施設の中で最上流に位置する水力発電施設で，東部電力株式会社が建設。桁行７間梁間３間半規模で，平屋建，切妻造，瓦棒鉄板葺とした小規模な木造建築物。外装は賀美発電所と同様下見板張で，小屋組は木造のキングポストトラスとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004317"},{"id":"00004319","register_sub_id":"101","register_pk":"105309","name":"徳田発電所余水路","kana":"とくだはつでんしょよすいろ","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県常陸太田市徳田町","lat":36.79895083,"lng":140.49278041,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"コンクリート造、延長254m、石積護岸11m付","structure_material":"コンクリート造","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0149","desc":"発電所本館の上方に位置する水槽からの余水を里川に導くための水路。２３ｍ長のコンクリート造暗渠に，側壁法勾配３分の谷積とした２３１ｍ長の開渠を連続させ，底部をモルタル塗とする。水圧鉄管路北側の斜面を直線状に貫き，放水路上流側で里川に流れ込む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004319"},{"id":"00001400","register_sub_id":"101","register_pk":"102390","name":"花貫川第一発電所第3号水路橋（めがね橋）","kana":"はなぬきがわだいいちはつでんしょだいさんごうすいろきょう（めがねばし）","category":"生活関連","subcategory":"土木構造物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県高萩市大字秋山字板木2989","lat":36.72784565,"lng":140.64270476,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"鉄筋コンクリート造2連アーチ橋、橋長77m、幅員2m","structure_material":"鉄筋コンクリート造2連アーチ橋","registered":"1999.11.18(平成11.11.18)","register_no":"08 － 0016","desc":"花貫ダムと花貫川第一発電所間の送水路の一部をなす長さ約７７ｍの水路橋。支間約２６ｍの２連ＲＣアーチからなる。スパンドレル部に位置する木造桁橋の橋脚部材を想わせる鉛直材に，我が国の橋梁分野におけるＲＣ導入初期の造形が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001400"},{"id":"00000028","register_sub_id":"101","register_pk":"101018","name":"水戸市水道低区配水塔","kana":"みとしすいどうていくはいすいとう","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"low","period":"昭和前","pref":"茨城県","address":"茨城県水戸市北見町126-14","lat":36.37833765,"lng":140.47562267,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造、高さ21.6m、直径11.2m","structure_material":"鉄筋コンクリート造","registered":"1996.12.20(平成8.12.20)","register_no":"08 － 0002","desc":"水戸市街の低地部分に給水を行うために建設された配水塔。設計は水道技師後藤鶴松で工事は市の直営で行われた。２階塔屋部の壁面にある浮彫彫刻や１階入口の装飾等に特徴があり，建設直後に既に水戸市の新名所として評判になる等，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000028"},{"id":"00016496","register_sub_id":"101","register_pk":"574858","name":"旧遊楽園（茂木佐公園）塔","kana":"きゅうゆうらくえん（もぎさこうえん）とう","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県野田市野田字東中町350-4","lat":35.937995,"lng":139.86641778,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造、高さ6.8m、面積1.3㎡","structure_material":"鉄筋コンクリート造","registered":"2026.02.10(令和8.02.10)","register_no":"12 - 0342","desc":"醤油醸造家が地域に開放した児童公園の中央に立つ塔。高さ六・八メートル、鉄筋コンクリート造モルタル洗出の角柱で、頂部を相輪風につくる。街灯兼時計塔で、かつて基部四面に水栓と流しを備えた。公園開設とともに野田における電力と水道の供給を示す塔。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016496"},{"id":"00011878","register_sub_id":"101","register_pk":"211139","name":"千葉県水道局栗山配水塔","kana":"ちばけんすいどうきょくくりやまはいすいとう","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県松戸市栗山198","lat":35.755237,"lng":139.897764,"geo_status":"db","era":"昭和12年／昭和38年・同52年・平成元年・同5年・同23年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造、内径15m、高さ32m、基礎土塁及び階段4基付","structure_material":"鉄筋コンクリート造","registered":"2017.10.27(平成29.10.27)","register_no":"12-236","desc":"昭和一五年に給水を開始した旧古ヶ崎浄水場の円筒型高架水槽。内径一五メートル、高さ三二メートルで、下部に従い緩やかに壁を厚くした耐圧構造となっている。ドーム状の屋根の塔頂部にパーゴラ風の通気口が付く。地域のランドマークとなる配水塔である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011878"},{"id":"00006264","register_sub_id":"101","register_pk":"107248","name":"千葉県水道局千葉高架水槽","kana":"ちばけんすいどうきょくちばこうかすいそう","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県千葉市中央区矢作町670","lat":35.606308,"lng":140.137741,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造、高さ30m、面積199㎡、階段付","structure_material":"鉄筋コンクリート造","registered":"2007.07.31(平成19.07.31)","register_no":"12 － 0070","desc":"ＪＲ千葉駅より約２ｋｍ東方，都川に面する水道用地に建つ高区配水用の施設。高さ３０ｍ規模の正十二角形平面の鉄筋コンクリート造構造物で，頂部に水槽を収め，躯体の北側に玄関及び階段室を設ける。高台にそびえ，地域のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006264"},{"id":"00011877","register_sub_id":"101","register_pk":"211124","name":"千葉県水道局千葉分場１号配水池","kana":"ちばけんすいどうきょくちぶんじょう１ごうはいすいち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県千葉市中央区矢作町670","lat":35.606434,"lng":140.138149,"geo_status":"db","era":"昭和12年／平成26年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造、内径29m、有効水深4.3m、基礎土塁及び階段4基付","structure_material":"鉄筋コンクリート造","registered":"2017.10.27(平成29.10.27)","register_no":"12-235","desc":"昭和一一年に通水された千葉県営水道創設時からの配水池。高架水槽と並ぶ。鉄筋コンクリート造半地下構造。円形の平面に矩形の弁室を張出す。アールデコ風の階段を上がると、芝張りの屋上にアールデコ風中央塔を飾る。戦前の水道施設として重要。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011877"},{"id":"00011646","register_sub_id":"101","register_pk":"210662","name":"松ケ丘一号型街路灯","kana":"まつがおかいちごうがたがいろとう","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"千葉県","address":"千葉県流山市松ケ丘二丁目330-85","lat":35.847624,"lng":139.950028,"geo_status":"db","era":"昭和32年頃／平成25年移設","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"コンクリート造、高さ4.4m","structure_material":"コンクリート造","registered":"2017.06.28(平成29.06.28)","register_no":"12-0226","desc":"昭和三〇年代に開発された住宅地に、防犯等のため要所に設置された街路灯。コンクリート製、高さ四・四メートルで、フルーティングを設けるなど様式建築の柱を模し、頂部に円形電灯を置く。地域の歴史を今に伝えるのみならず、意匠的にも特徴ある街路灯。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011646"},{"id":"00007977","register_sub_id":"101","register_pk":"128809","name":"旧野方配水塔","kana":"きゅうのかたはいすいとう","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都中野区江古田1-3","lat":35.72464956,"lng":139.67485374,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造、屋根コンクリートアスファルト塗、建築面積187㎡、石柵付","structure_material":"鉄筋コンクリート造","registered":"2010.01.15(平成22.01.15)","register_no":"13-0255","desc":"東京２３区北西部への配水を目的として建設。高さ３４ｍの鉄筋コンクリート造構造物で、東側に階段室、頂部に換気塔を付け、水槽周壁上部にはアーチ形窓を配する。壁体内の漏水防止用鋼板に最初期の溶接技術を用い、ドーム付円筒形水道塔としても最初期の事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007977"},{"id":"00000725","register_sub_id":"101","register_pk":"101715","name":"川島町旧配水計量室上屋","kana":"かわしまちょうきゅうはいすいけいりょうしつうわや","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横浜市保土ケ谷区川島町578-12","lat":35.46599524,"lng":139.57577709,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"煉瓦造平屋建，銅板葺，建築面積25㎡","structure_material":"煉瓦造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"14 － 0022","desc":"横浜市水道第二次拡張の施設。同時期建設の西谷浄水場の下方に位置する。浄水場内の上屋と同様の造りであるが，場外に所在するだけに，外装には横黒・鼻黒煉瓦を用い，開口部のグリルなども装飾的にするなど格別の仕様がとられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000725"},{"id":"00015006","register_sub_id":"101","register_pk":"529284","name":"旧神奈川県営湘南水道鎌倉加圧ポンプ所","kana":"きゅうかながわけんえいしょうなんすいどうかまくらかあつぽんぷじょ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市長谷四丁目527-1他","lat":35.31773056,"lng":139.53297222,"geo_status":"db","era":"昭和11年／昭和40年・令和4年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階建、建築面積290㎡","structure_material":"鉄筋コンクリート造平屋一部2階建","registered":"2024.08.15(令和6.08.15)","register_no":"14 - 0351","desc":"大仏隧道の鎌倉口に建ち、上水を加圧送水したポンプ所。鉄筋コンクリート造平屋建、外壁スクラッチタイル貼、腰を人造石とし縦長窓と単窓を並べる。内部は矩形平面で北寄りを二層とし、階段廻りを幾何学的意匠で飾る。簡明な構成で入口等要所の意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015006"},{"id":"00000724","register_sub_id":"101","register_pk":"101714","name":"旧横浜居留地煉瓦造下水道マンホール","kana":"きゅうよこはまきょりゅうちれんがづくりげすいどうまんほーる","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県横浜市中区日本大通","lat":35.44772604,"lng":139.64394254,"geo_status":"db","era":"明治14～16","year":1881,"year_source":"converted","year_min":1881,"year_max":1881,"year_label":null,"structure":"外径長4.0m，外径幅3.2m，沈殿槽部深さ2.1m，前後卵形管総延長41.5m附属","structure_material":"外径長4.0m","registered":"1998.09.02(平成10.09.02)","register_no":"14 － 0021","desc":"明治初年のブラントン設計による陶管下水道を煉瓦造に改造した際の施設。当時神奈川県御用掛の三田善太郎が計画にあたる。日本人の計画になる最初の近代下水道遺構として貴重。２本の中下水卵型管を接続する。大桟橋入口の開港広場に保存展示されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000724"},{"id":"00004730","register_sub_id":"101","register_pk":"105720","name":"横須賀市上下水道局逸見浄水場緩速ろ過池調整室Ⅰ","kana":"よこすかしじょうげすいどうきょくへみじょうすいじょうかんそくろかちちょうせいしついち","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横須賀市西逸見町2-10","lat":35.27837156,"lng":139.64811787,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積17㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0111","desc":"横須賀市中心部より西方に位置する水道施設。ほぼ南北に４基配された緩速ろ過池のうち，北端に位置する一号ろ過池に附属する調整室。アングル材を用いて組み上げられた鉄骨を，梁間方向に３基並べ，鉄筋コンクリート造スラブを支える珍しい構造形式をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004730"},{"id":"00004877","register_sub_id":"101","register_pk":"105867","name":"横須賀市上下水道局逸見浄水場緩速ろ過池調整室Ⅲ","kana":"よこすかしじょうげすいどうきょくへみじょうすいじょうかんそくろかちちょうせいしつさん","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横須賀市西逸見町2-10","lat":35.27790266,"lng":139.64795837,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積17㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0113","desc":"調整室Ⅱの約２０ｍ南側に位置する。明治４５年２月から大正１０年３月にかけて実施された横須賀軍用水道拡張工事の一環として建設。他３棟と同様に，鉄筋コンクリート技術が確立される前の，形式に囚われない構法が見所。水道拡張工事の計画指導は石黒弘毅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004877"},{"id":"00004876","register_sub_id":"101","register_pk":"105866","name":"横須賀市上下水道局逸見浄水場緩速ろ過池調整室Ⅱ","kana":"よこすかしじょうげすいどうきょくへみじょうすいじょうかんそくろかちちょうせいしつに","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横須賀市西逸見町2-10","lat":35.27813585,"lng":139.64803134,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積17㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0112","desc":"調整室Ⅰの約２０ｍ南側に位置する。緩速ろ過池の西辺に隣接してたち，配水池に至るろ過水の水量調節するバルブ等をおさめる。桁行４．６ｍ，梁間３．７ｍの規模を有する，鉄筋コンクリート造平屋建，銅板葺，妻入で，他の調整室と同様の構造形式とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004876"},{"id":"00004878","register_sub_id":"101","register_pk":"105868","name":"横須賀市上下水道局逸見浄水場緩速ろ過池調整室Ⅳ","kana":"よこすかしじょうげすいどうきょくへみじょうすいじょうかんそくろかちちょうせいしつよん","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横須賀市西逸見町2-10","lat":35.27767824,"lng":139.64787805,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積17㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0114","desc":"調整室Ⅲの約２０ｍ南側に位置する。他３棟と同様の構造形式。基礎には花崗岩を用い，鉄筋コンクリート躯体の四周には，デザインの簡略化された柱形と幅の異なる２種類の縦長窓を密に配す。正面と背面には菱形模様に楕円を浮彫したメダイオン風の装飾を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004878"},{"id":"00004879","register_sub_id":"101","register_pk":"105869","name":"横須賀市上下水道局逸見浄水場配水池西入口","kana":"よこすかしじょうげすいどうきょくへみじょうすいじょうはいすいちにしいりぐち","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横須賀市西逸見町2-10","lat":35.27782357,"lng":139.64714863,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造、建築面積20㎡","structure_material":"鉄筋コンクリート造","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0116","desc":"東入口と観測路で繋がる配水池西入口の建屋。鉄筋コンクリートで築かれた，正方形平面の塔状の建造物で，浄水場のランドマーク的な構造物。開口部と内部空間を広くとる採光と換気に配慮したつくりで，デザインは，東入口と同様にセセッション風とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004879"},{"id":"00004731","register_sub_id":"101","register_pk":"105721","name":"横須賀市上下水道局逸見浄水場配水池東入口","kana":"よこすかしじょうげすいどうきょくへみじょうすいじょうはいすいちひがしいりぐち","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横須賀市西逸見町2-10","lat":35.27769576,"lng":139.64775287,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造、建築面積20㎡","structure_material":"鉄筋コンクリート造","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0115","desc":"緩速ろ過池西方に位置する，半地下構造の配水池東側中央にたてられた鉄筋コンクリート造の建築。窓と入口のアーチ頂部に誇張されたデザインの要石形を浮彫する。直線を基調としたセセッション風の幾何学的デザインに，新たな時代の造形感覚を窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004731"},{"id":"00004732","register_sub_id":"101","register_pk":"105722","name":"横須賀市上下水道局逸見浄水場ベンチュリーメーター室","kana":"よこすかしじょうげすいどうきょくへみじょうすいじょうべんちゅりーめーたーしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横須賀市西逸見町2-10","lat":35.27867981,"lng":139.64870999,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積18㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0117","desc":"敷地北方に位置する。逸見浄水場から，西北に約５３ｋｍ離れた半原水源地より導かれた原水の流量を計測するために築かれる。桁行４．７ｍ，梁間３．８ｍの鉄筋コンクリート造平屋建で，中央に換気塔を設ける。近代水道の仕組みを今に伝える貴重な施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004732"},{"id":"00001506","register_sub_id":"101","register_pk":"102496","name":"横須賀市水道局走水水源地鉄筋コンクリート造浄水池","kana":"よこすかしすいどうきょくはしりみずすいげんちてっきんこんくりーとづくりじょうすいち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県横須賀市走水1-1-26","lat":35.26284836,"lng":139.72273524,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"鉄筋コンクリート造、面積517㎡","structure_material":"鉄筋コンクリート造","registered":"2000.02.15(平成12.02.15)","register_no":"14 － 0030","desc":"走水水源地の第２期拡張工事で建設された上屋付き浄水池。内部は鉄筋コンクリート造の５連馬蹄形ヴォールトで構成され，外壁には石で縁取りされた丸窓を一列に配す。設計は海軍技師伊藤誠吉とされる。日本最初期の鉄筋コンクリート建造物のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001506"},{"id":"00001505","register_sub_id":"101","register_pk":"102495","name":"横須賀市水道局走水水源地煉瓦造貯水池","kana":"よこすかしすいどうきょくはしりみずすいげんちれんがづくりちょすいち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県横須賀市走水1-1-26","lat":35.26252479,"lng":139.72322685,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"煉瓦造、面積143㎡","structure_material":"煉瓦造","registered":"2000.02.15(平成12.02.15)","register_no":"14 － 0029","desc":"横須賀軍港水道走水水源地の第１期拡張工事で建設された上屋付き煉瓦造貯水池。内部空間を構成する扁平ヴォールトが，入口・丸窓を左右対称に配した壁面で覆われ，屋上は盛土される。横須賀鎮守府経理部建築科の海軍技師井川喜久蔵，堀池好之助らが担当。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001505"},{"id":"00000821","register_sub_id":"101","register_pk":"101811","name":"横浜市水道局青山水源事務所旧青山取水口","kana":"よこはましすいどうきょくあおやますいげんじむしょきゅうあおやましゅすいこう","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県相模原市緑区青山3482","lat":35.57816429,"lng":139.22326313,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"玉石詰鉄柵造取入堤（高さ4.6m，長さ8.2m）及び流水水門（高さ2.4m），導水鉄管２条よりなる","structure_material":"玉石詰鉄柵造取入堤（高さ4.6m","registered":"1998.10.09(平成10.10.09)","register_no":"14 － 0023","desc":"相模川左岸におけるポンプアップによる横浜創設水道(明治２０年)取水施設を廃し，取水地を道志川上流右岸に移した際の遺構。流木除けの鉄柵の内側に玉石を詰め，英国グラスゴーのレイドロー・アンド・サンズ社製の鉄管を２本立てて直接取水する構造をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000821"},{"id":"00000822","register_sub_id":"101","register_pk":"101812","name":"横浜市水道局青山水源事務所旧青山沈殿池","kana":"よこはましすいどうきょくあおやますいげんじむしょきゅうあおやまちんでんち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県相模原市緑区青山3482","lat":35.57924167,"lng":139.22313432,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"コンクリート造，長さ34.2m，幅34.2m","structure_material":"コンクリート造","registered":"1998.10.09(平成10.10.09)","register_no":"14 － 0024","desc":"横浜市水道第１次拡張時（完工は明治３４年）の遺構。旧青山取水口に対応する沈殿池で，新設の川井浄水地と既設の野毛浄水地に送水した。コンクリート造，約３０ｍ角の規模で，２池に分け，法面を玉石貼りとする（第２次拡張時に約半分に縮小）。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000822"},{"id":"00000194","register_sub_id":"101","register_pk":"101184","name":"横浜市西谷浄水場配水池配水井上屋","kana":"よこはましにしやじょうすいじょうはいすいちはいすいせいうわや","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市保土ケ谷区川島町522","lat":35.46657072,"lng":139.57201695,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造平屋建，銅板葺，建築面積30㎡","structure_material":"煉瓦造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"14 － 0007","desc":"配水池を挟んで浄水井上屋と対照の位置に、これと同型同規模の配水井上屋が設けられている。建築面積は２２平方メートルと小規模な煉瓦造の建築であるが、端整な意匠の上屋として西谷浄水場の記念的存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000194"},{"id":"00000189","register_sub_id":"101","register_pk":"101179","name":"横浜市西谷浄水場濾過池整水室上屋３号棟","kana":"よこはましにしやじょうすいじょうろかちせいすいしつうわやさんごうとう","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市保土ケ谷区川島町522","lat":35.46641218,"lng":139.57012011,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造平屋建，銅板葺，建築面積13㎡","structure_material":"煉瓦造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"14 － 0002","desc":"横浜水道第２次拡張工事により、大正４年に西谷の地に完成した水道施設の遺構の一部で、公園風に整備された浄水場のほぼ中心部に位置する。一帯は幾何学的な庭園風の構成となって保存され、浄水場の象徴的存在となっている。設計は横浜市水道臨時事業部。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000189"},{"id":"00000191","register_sub_id":"101","register_pk":"101181","name":"横浜市西谷浄水場濾過池整水室上屋７号棟","kana":"よこはましにしやじょうすいじょうろかちせいすいしつうわやななごうとう","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市保土ケ谷区川島町522","lat":35.46631026,"lng":139.57015408,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造平屋建，銅板葺，建築面積13㎡","structure_material":"煉瓦造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"14 － 0004","desc":"整水室上屋は、４基とも内法１０フィート角の正方形平面を保つ。花崗岩切石の土台に連歌枚積みで外壁を造り、南北の向かい合わせ面に扉を開く。銅板葺の特異な宝形屋根をかけた小さいながらも建築として完結した煉瓦造の上屋として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000191"},{"id":"00000192","register_sub_id":"101","register_pk":"101182","name":"横浜市西谷浄水場濾過池整水室上屋８号棟","kana":"よこはましにしやじょうすいじょうろかちせいすいしつうわやはちごうとう","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市保土ケ谷区川島町522","lat":35.46640652,"lng":139.57065802,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造平屋建，銅板葺，建築面積13㎡","structure_material":"煉瓦造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"14 － 0005","desc":"整水室上屋は、４基とも小規模な煉瓦造の建物で、基礎及び軒廻りを石造とし、外壁にも３筋の花崗岩の帯を入れアクセントとする。各壁面にはアーチを設けて扉口や小窓を開く。煉瓦の赤、花崗岩の白、銅板の緑が整然と配置された建物群を魅力あるものにしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000192"},{"id":"00000190","register_sub_id":"101","register_pk":"101180","name":"横浜市西谷浄水場濾過池整水室上屋４号棟","kana":"よこはましにしやじょうすいじょうろかちせいすいしつうわやよんごうとう","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市保土ケ谷区川島町522","lat":35.46650278,"lng":139.57063537,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造平屋建，銅板葺，建築面積13㎡","structure_material":"煉瓦造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"14 － 0003","desc":"整水室は濾過池の水を浄水管で配水池に送る施設で、濾過地に対応して１基づつ造られている。上屋は４基とも昭和４８年の近代化工事で機能を失ったが、優れた場内環境を保つ上で欠かせない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000190"},{"id":"00000193","register_sub_id":"101","register_pk":"101183","name":"横浜市西谷浄水場配水池浄水井上屋","kana":"よこはましにやじょうすいじょうはいすいちじょうすいせいうわや","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市保土ケ谷区川島町522","lat":35.46654808,"lng":139.57102606,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造平屋建，銅板葺，建築面積22㎡","structure_material":"煉瓦造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"14 － 0006","desc":"濾過池の東に配水池が配され、浄水井上屋と配水井上屋が設けられている。４基の整水室上屋の東西軸線の東方に建つ八角形の煉瓦造の上屋。平面が八角で規模も一回り大きいが、構造及び意匠は整水井上屋と共通し、一帯ののびやかな景観は広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000193"},{"id":"00003401","register_sub_id":"101","register_pk":"104391","name":"亀田町上水道高架水槽","kana":"かめだまちじょうすいどうこうかすいそう","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県新潟市江南区亀田水道町2-4-3","lat":37.87070497,"lng":139.11803724,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄骨造、鉄製水槽、高さ18m","structure_material":"鉄骨造","registered":"2003.07.01(平成15.07.01)","register_no":"15 － 0162","desc":"新潟市境に近い市街地東部に位置する浄水場敷地内の配水塔。山形鋼を用いた６本の鉄骨柱を正六角形平面上にたち上げ，上部に直径７．８ｍ，高さ５．４ｍの円筒槽を頂く。町の近代化を支えたランドマークで，水道タンクの名で住民に広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003401"},{"id":"00012309","register_sub_id":"101","register_pk":"531633","name":"旧白根配水塔","kana":"きゅうしろねはいすいとう","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県新潟市南区上下諏訪木字川原10-1","lat":37.75712778,"lng":139.00930278,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造、金属板葺、直径8.1m、高さ26m","structure_material":"鉄筋コンクリート造","registered":"2018.05.10(平成30.05.10)","register_no":"15-478","desc":"昭和六年の大火を契機に建設された上水道施設の配水塔。円塔状の躯体頂部に円筒形の貯水槽を置き、円錐形の屋根をかける。内部は吹抜けで、階段と梯子を設けて貯水槽外周を廻るベランダに至る。生活基盤を支えた近代施設の象徴として市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012309"},{"id":"00009746","register_sub_id":"101","register_pk":"195575","name":"旧中島浄水場監視室棟","kana":"きゅうなかじまじょうすいじょうかんししつとう","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県長岡市水道町3-247-2","lat":37.45705172,"lng":138.8430925,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積57㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"15 － 0383","desc":"ポンプ室棟の南西側に建ち、略正方形平面の鉄筋コンクリート造平屋建、陸屋根である。各面中央に半円アーチを象るパラペットを立上げ、アーチ周りをドイツ壁仕上げとする。腰を石貼とし、外壁に柱形を表して石造風に目地を切り、ポンプ室棟と景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009746"},{"id":"00009745","register_sub_id":"101","register_pk":"195574","name":"旧中島浄水場ポンプ室棟","kana":"きゅうなかじまじょうすいじょうぽんぷしつとう","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県長岡市水道町3-247-2","lat":37.45723256,"lng":138.84324003,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積295㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"15 － 0382","desc":"Ｌ字形平面の鉄筋コンクリート造平屋建、陸屋根である。正面側は高揚ポンプ室で、中央の玄関ポーチ上に半円アーチを象るパラペットを立上げ、左右対称の立面に大オーダーを配する。腰を石貼とする石造風の重厚な外観で、要所をアールデコ意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009745"},{"id":"00009747","register_sub_id":"101","register_pk":"195576","name":"旧中島浄水場予備発電機室棟","kana":"きゅうなかじまじょうすいじょうよびはつでんきしつとう","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県長岡市水道町3-247-2","lat":37.45723256,"lng":138.84302588,"geo_status":"db","era":"昭和2／昭和37増築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造平屋建、金属板葺、建築面積203㎡、渡廊下付","structure_material":"鉄筋コンクリート造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"15 － 0384","desc":"ポンプ室棟の西側に建ち、鉄筋コンクリート造平屋建、切妻造金属板葺である。外壁はモルタル仕上げで、パラペットを立上げて軒下に歯飾りを並べ、柱形の間には縦長窓や小窓を配してアクセントとする。ポンプ室棟と比べ装飾を抑えた外観で、景観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009747"},{"id":"00008838","register_sub_id":"101","register_pk":"162281","name":"三条市水道局大崎浄水場１号・２号及び３号緩速ろ過池","kana":"さんじょうしすいどうきょくおおさきじょうすいじょういちごう・にごうおよびさんごうかんそくろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新4420-3","lat":37.60834377,"lng":138.99766297,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"コンクリート造一部鉄筋コンクリート造、面積1913㎡","structure_material":"コンクリート造一部鉄筋コンクリート造","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0347","desc":"事務室棟の南側に位置する。鉄筋コンクリート造、南北70.9ｍ東西28ｍ深さ2.7ｍで、三槽のろ過池からなる。各辺頂部に笠石を廻らし、各池底の中央に集水溝を設ける。創設以来、現役で使われているろ過池。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008838"},{"id":"00008837","register_sub_id":"101","register_pk":"162280","name":"三条市水道局大崎浄水場旧番宅","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうきゅうばんたく","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新4420-3","lat":37.60947181,"lng":138.99703779,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積122㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0346","desc":"送水ポンプ室と配水池の間に建つ旧水道局官舎。木造平屋建、桁行16.4ｍ梁間7.3ｍ、寄棟造桟瓦葺、桁行を二分し二戸を設け、正面に各戸の玄関、背面に便所を張出し、外壁は下見板張とする。昭和初期の浄水場施設の一端を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008837"},{"id":"00008836","register_sub_id":"101","register_pk":"162279","name":"三条市水道局大崎浄水場事務室棟","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうじむしつとう","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新4420-3","lat":37.60877868,"lng":138.99748629,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0345","desc":"敷地中央部に西面して建つ。木造平屋建、桁行5.5ｍ梁間7.9ｍ、切妻造桟瓦葺、北西部を切欠いて玄関ポーチとし、背面に手洗いを張出す。外壁はモルタル洗出しで腰壁をタイル貼とする。神社本殿の流造風の屋根が特徴の浄水場の中心施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008836"},{"id":"00008834","register_sub_id":"101","register_pk":"162277","name":"三条市水道局大崎浄水場取水ポンプ場ポンプ室","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうしゅすいぽんぷじょうぽんぷしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新316","lat":37.60715678,"lng":138.99353272,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積132㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0343","desc":"五十嵐川東岸に建ち、木造平屋建、桁行13.7ｍ梁間7.3ｍ、切妻造鉄板葺、正面に切妻造の玄関、背面に寄棟造の付属屋を突出する。外壁はモルタル塗、内部中央に内径5.6ｍルの取水井を設ける。小住宅風の瀟洒な外観である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008834"},{"id":"00008835","register_sub_id":"101","register_pk":"162278","name":"三条市水道局大崎浄水場取水ポンプ場門","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうしゅすいぽんぷじょうもん","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新258","lat":37.60729009,"lng":138.99367463,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"コンクリート造、延長7.9m","structure_material":"コンクリート造","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0344","desc":"ポンプ室の東側に位置する。コンクリート造、高さ2.1ｍの親柱を3.8ｍ間隔で配し、斜め前方の高さ1.3ｍの脇柱と袖壁で繋ぎ、各柱上に笠石を造り出す。取水ポンプ室と一体で良好な歴史的景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008835"},{"id":"00008839","register_sub_id":"101","register_pk":"162282","name":"三条市水道局大崎浄水場洗砂場","kana":"さんじょうしすいどうきょくおおさきじょうすいじょうせんしゃじょう","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県三条市中新4420-3","lat":37.60843211,"lng":138.99782606,"geo_status":"db","era":"昭和8年／昭和中期移築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄骨造平屋建、鉄板葺、建築面積19㎡","structure_material":"鉄骨造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0348","desc":"ろ過池の東側に位置する、ろ過層の砂類を洗浄するための施設。桁行4.9ｍ梁間3.8ｍの吹放ちの建物で、切妻造鉄板葺である。柱下部を鉄筋コンクリート造とし、上部は古レールをＹ字形に組んで木造の小屋組を受ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008839"},{"id":"00000657","register_sub_id":"101","register_pk":"101647","name":"水道タンク","kana":"すいどうたんく","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県長岡市水道町3-11-1","lat":37.45666341,"lng":138.84310213,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造，一部鉄製，高さ41.5m","structure_material":"鉄筋コンクリート造","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0002","desc":"創設長岡市水道のモニュメントで，長岡のランドマークとして親しまれている。配水塔で，塔体は鉄筋コンクリート造６階建，平面円形で外周にトスカナ式のピラスターを付す。タンク部は鉄骨造の架構に鋼製の水槽を納める。金井彦三郎の設計と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000657"},{"id":"00009594","register_sub_id":"101","register_pk":"194590","name":"燕市旧浄水場配水塔","kana":"つばめしきゅうじょうすいじょうはいすいとうとう","category":"生活関連","subcategory":"その他工作物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県燕市水道町1-3-28","lat":37.65740398,"lng":138.91833121,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"鉄筋コンクリート造、高さ31m、直径10m","structure_material":"鉄筋コンクリート造","registered":"2013.06.21(平成25.06.21)","register_no":"15 － 0381","desc":"浄水場に設置された鉄筋コンクリート造の配水塔で、総高三二メートル。支持台部は円錐台形で八方に柱形を見せ、内部に四階の床を張る。上部水槽は八角平面。一階北に戸口を設け、各階四箇所の窓を開く。四階から外部梯子で登る水槽外周の歩廊が軽快である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009594"},{"id":"00002377","register_sub_id":"101","register_pk":"103367","name":"上滝発電所","kana":"かみだきはつでんしょ","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県富山市中滝字小野海浦割3-1","lat":36.603237,"lng":137.3130692,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積678㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"16 － 0063","desc":"富山県県営電気事業第１期の常願寺川水系３発電所のうち最下流に位置する。常願寺川左岸に位置し，松ノ木発電所からの水を落差約６７ｍで導き３機の水車を回す。鉄筋コンクリート造平屋一部２階建で，３発電所のうち最も規模が大きく，屋根を陸屋根状に造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002377"},{"id":"00002763","register_sub_id":"101","register_pk":"103753","name":"小牧ダム","kana":"こまきだむ","category":"生活関連","subcategory":"土木構造物","type_guess":"堰堤","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県砺波市庄川町大字小牧字矢ヶ瀬74","lat":36.55703411,"lng":137.00850014,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"重力式コンクリート造堰堤、堤長301m、堤高79m、副堰堤及び魚道付","structure_material":"重力式コンクリート造堰堤","registered":"2002.06.25(平成14.06.25)","register_no":"16 － 0069","desc":"庄川に築かれた発電用堰堤。アーチ平面の本格的な重力式コンクリート造ハイダムで，中央部にテンターゲート付越流部，右岸側にエレベータ式魚道，左岸側に運材設備を設ける。地震力を考慮した設計により飛躍的に大型化した構造物で，東洋一のダムと呼ばれた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002763"},{"id":"00000127","register_sub_id":"101","register_pk":"101117","name":"清水町配水塔資料館旧第３源井上屋","kana":"しみずまちはいすいとうしりょうかんきゅうだいさんげんせいうわや","category":"生活関連","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"富山県","address":"富山県高岡市清水町1-7-30","lat":36.74048141,"lng":137.00328868,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋建，銅板葺，建築面積6.6㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"16 － 0005","desc":"地下水を汲み上げる源井の上屋である。鉄筋コンクリート造ではあるが，煉瓦の外壁を持ち，八角形の平面とあいまって愛らしい外観を見せている。配水塔とともに当時の科学技術の粋を集めた施設のシンボルとして広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000127"},{"id":"00000038","register_sub_id":"101","register_pk":"101028","name":"清水町配水塔資料館旧配水塔","kana":"しみずまちはいすいとうしりょうかんきゅうはいすいとう","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"富山県","address":"富山県高岡市清水町1-7-30","lat":36.74106804,"lng":137.00355779,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、高さ29.7m、直径11.4m","structure_material":"鉄筋コンクリート造","registered":"1996.12.20(平成8.12.20)","register_no":"16 － 0002","desc":"昭和６年に完成した高岡市の水道施設の一部。当時の最新科学の粋を集めた水源施設のシンボル的存在である。鉄筋コンクリート造の４層の上に銅板張りの貯水槽が乗る。平成５年より資料館として活用され，通水当時の工具などを展示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000038"},{"id":"00000128","register_sub_id":"101","register_pk":"101118","name":"清水町配水塔資料館水源地水槽","kana":"しみずまちはいすいとうしりょうかんすいげんちすいそう","category":"生活関連","subcategory":"その他工作物","type_guess":"発電","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県高岡市清水町1-7-30","lat":36.74074942,"lng":137.00384913,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造，長さ30.3m，幅22.7m，高さ3.0m","structure_material":"鉄筋コンクリート造","registered":"1997.05.07(平成9.05.07)","register_no":"16 － 0006","desc":"鉄筋コンクリート造で，長さ30.3ｍ，幅22.7ｍ，高さ3.0ｍの大規模な半地下式の構造物。現在も予備の水槽としての機能をもつが，上部が公園化され市民の憩いの場になっており，高岡の市民生活を支える施設として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000128"},{"id":"00002379","register_sub_id":"101","register_pk":"103369","name":"中地山発電所","kana":"なかちやまはつでんしょ","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県富山市中地山字上中地山割1-2","lat":36.56804605,"lng":137.36617948,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積237㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"16 － 0065","desc":"富山県電気局による最初の３発電所のうち，常願寺川の最上流に位置し，最も早い大正１３年２月に稼働した。鉄筋コンクリート造，切妻屋根の平屋建で，水車・発電機１対と配電施設等を１室に収める。３発電所とも県内初期鉄筋コンクリート造建築とされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002379"},{"id":"00000039","register_sub_id":"101","register_pk":"101029","name":"入善町下山芸術の森アートスペース（旧下山発電所）","kana":"にゅうぜんまちにざやまげいじゅつのもりあーとすぺーす（きゅうにざやまはつでんしょ）","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県下新川郡入善町下山364-1","lat":36.90714499,"lng":137.53141345,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造2階建、鉄板葺、建築面積558㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"16 － 0003","desc":"発電所の建屋を町が払い下げを受け美術館とした建物。富山平野特有の低落差の河岸段丘を利用した小型の水力発電所で，その立地と赤煉瓦を用いた外観の意匠に特徴がある。富山平野の地形やそれを利用した近代の景観を知る上で特に必要な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000039"},{"id":"00002378","register_sub_id":"101","register_pk":"103368","name":"松ノ木発電所","kana":"まつのきはつでんしょ","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県富山市松木字大下割446","lat":36.57245853,"lng":137.34801483,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積537㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"16 － 0064","desc":"大正１０年１１月同時着工された３発電所のひとつで，常願寺川左岸に位置し，中地山発電所の放水を導水し２機の水車を回す。鉄筋コンクリート造平屋一部２階建で，下弦材をアーチにした鉄骨トラスにより切妻状の屋根を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002378"},{"id":"00004953","register_sub_id":"101","register_pk":"105943","name":"浅野川大橋詰火の見櫓","kana":"あさのがわおおはしづめひのみやぐら","category":"生活関連","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県金沢市東山3-1-2先","lat":36.572456,"lng":136.664551,"geo_status":"db","era":"大正13／昭和46改造","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄骨造、高さ11m","structure_material":"鉄骨造","registered":"2005.11.10(平成17.11.10)","register_no":"17 － 0128","desc":"市内に現存する最古の火の見櫓。浅野川大橋の北詰にあり，鋳鉄製銘板から，施工は市内の高田商会。手摺を含めると高さ約１１ｍ，三角形平面の鉄骨造で，柱や横材等は山形鋼を用い，筋違は鋼棒とし，一部にアーチを使い，大型鉄骨造の櫓とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004953"},{"id":"00011282","register_sub_id":"101","register_pk":"209118","name":"大桑配水場旧計量室","kana":"おおくわはいすいじょうきゅうけいりょうしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市大桑町サ乙3-3","lat":36.525669,"lng":136.686667,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積8.5㎡、地階付","structure_material":"鉄筋コンクリート造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"17－0259","desc":"隣接する配水池から延びる導水管の流量を計測していた施設で、約三メートルの正方形平面に導水管を視認できる地下室を持つ。屋根や外壁が直線的意匠で飾られ、窓格子には渦模様に梅鉢に水の標章を配するなど、末浄水場の施設群と一連で計画された意匠を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011282"},{"id":"00002231","register_sub_id":"101","register_pk":"103221","name":"末浄水場一号緩速沈澱池","kana":"すえじょうすいじょういちごうかんそくちんでんち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.512432,"lng":136.700455,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造、面積2848㎡","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0043","desc":"市中心部の南方，犀川中流部に位置する。金沢市創設水道の浄水場施設で，一号沈澱池は，敷地南部に位置する面積２８４８㎡の鉄筋コンクリート造水槽。下部約４ｍの側壁を法面勾配１割５分でつくり，隅部に同勾配で約８ｍ長の階段１基が築かれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002231"},{"id":"00002234","register_sub_id":"101","register_pk":"103224","name":"末浄水場一号緩速ろ過池","kana":"すえじょうすいじょういちごうかんそくろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.513008,"lng":136.698639,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、面積1375㎡、浄水井付","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0046","desc":"沈澱池の西端から引かれた水が，低地にある６基の緩速ろ過池に配水される。一号ろ過池はろ過池全体の東南端にあり，他と同様にほぼ垂直に切り立った鉄筋コンクリート造壁面に囲まれた面積１３７５㎡の構造物で，池の北側にコンクリート造浄水井を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002234"},{"id":"00002240","register_sub_id":"101","register_pk":"103230","name":"末浄水場緩速浄水集合井","kana":"すえじょうすいじょうかんそくじょうすいしゅうごうせい","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.51401263,"lng":136.69711278,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積26㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0052","desc":"敷地の西端，緩速ろ過池中央通路の先端部に位置する。当初計画されていた円形平面は，井面積拡大の要請により小判型平面となる。鉄筋コンクリート造上屋の側面に，大小３つの半円アーチを配し，スパンドレルに円をモチーフとした浮彫をあしらう。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002240"},{"id":"00002241","register_sub_id":"101","register_pk":"103231","name":"末浄水場緩速浄水ポンプ室","kana":"すえじょうすいじょうかんそくじょうすいぽんぷしつ","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.51412816,"lng":136.69720064,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積12㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0053","desc":"緩速浄水集合井の北側に位置する旧塩素滅菌室。ろ過池側を正面として建つ。矩形平面の平屋建鉄筋コンクリート造建築で，各立面を柱型と梁型により縁取る特徴的な意匠でまとめる。金沢市創設水道は大井清一，石井一夫によって計画・設計された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002241"},{"id":"00011283","register_sub_id":"101","register_pk":"209119","name":"末浄水場旧着水井上屋","kana":"すえじょうすいじょうきゅうちゃくすいせいうわや","category":"生活関連","subcategory":"建築物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.512267,"lng":136.699848,"geo_status":"db","era":"昭和7／平成26改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積87㎡、地階付","structure_material":"鉄筋コンクリート造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"17－0260","desc":"末浄水場の最初期の整備事業で建てられたもので、正面入口に西面して建つ。緩い曲線で持ち送られるパラペットや一段低く入口上部を回る庇が立面を構成し、丸窓や、外壁腰部の飾りがアクセントとなり、近代的水道施設として意図された装飾性が感じられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011283"},{"id":"00002238","register_sub_id":"101","register_pk":"103228","name":"末浄水場五号緩速ろ過池","kana":"すえじょうすいじょうごごうかんそくろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.513241,"lng":136.697983,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、面積1375㎡、浄水井付","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0050","desc":"三号緩速ろ過池の西側に位置する。正面開口部を凸型曲面で縁取り門柱形とした浄水井上屋を構える。上屋は，躯体の４隅を曲面で仕上げ，正面以外の各側面に２つの縦長を並置する。屋根を階段状造り，中央に小ドームを載せて外観にアクセントを与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002238"},{"id":"00002233","register_sub_id":"101","register_pk":"103223","name":"末浄水場三号緩速沈澱池","kana":"すえじょうすいじょうさんごうかんそくちんでんち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.513268,"lng":136.701035,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造、面積2848㎡","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0045","desc":"二号緩速沈澱池の北側にある。白山連峰に連なる山岳地帯を集水源とする犀川上流部から引かれた水は，正門前の道路下に敷設された導水管を通り，敷地南端正門横の着水井，緩速原水処理機を経由して，沈澱池の東側から前述２基の緩速沈澱池に均等に配水される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002233"},{"id":"00002236","register_sub_id":"101","register_pk":"103226","name":"末浄水場三号緩速ろ過池","kana":"すえじょうすいじょうさんごうかんそくろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.513111,"lng":136.698318,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、面積1375㎡、浄水井付","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0048","desc":"一号緩速ろ過池の西側に位置し，隔壁を兼ねた管理用通路によって両側のろ過池と仕切られる。ろ過池通路側の両端に管を１基ずつ設け溢水に備える。ろ過水を集水する浄水井は，コンクリート造水槽で，笠石に花崗石を用い，蓋を縞鋼板で覆う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002236"},{"id":"00002232","register_sub_id":"101","register_pk":"103222","name":"末浄水場二号緩速沈澱池","kana":"すえじょうすいじょうにごうかんそくちんでんち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.512844,"lng":136.700745,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造、面積2848㎡","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0044","desc":"一号緩速沈澱池の北側に位置する。他の沈澱池同様，地下湧水処理用の土管を池下方に敷設する。コンクリートの伸縮作用に備え，池全体が１２分割され，表面全体にモルタル工を施す。伸縮接手にアスファルトと鉛板を用い，池の水密性を高める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002232"},{"id":"00002235","register_sub_id":"101","register_pk":"103225","name":"末浄水場二号緩速ろ過池","kana":"すえじょうすいじょうにごうかんそくろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.513462,"lng":136.698959,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、面積1375㎡、浄水井付","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0047","desc":"一号緩速ろ過池の通路を挟んだ北側にある。伸縮作用を考慮し２５区画に分割し，煉瓦，多孔鉄筋コンクリート板，砂を敷いたろ床中央に，浄水井に向かって１／１１８の勾配を有す約０．９ｍ幅の集水渠を設ける。伸縮接手に緩速沈殿地と同様の加工を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002235"},{"id":"00002237","register_sub_id":"101","register_pk":"103227","name":"末浄水場四号緩速ろ過池","kana":"すえじょうすいじょうよんごうかんそくろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.513611,"lng":136.698593,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、面積1375㎡、浄水井付","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0049","desc":"二号緩速ろ過池の西側に位置する。池の南側に，鉄筋コンクリート造，建築面積１４㎡でほぼ正方形平面をした浄水井上屋を構える。上屋は，通路側を正面とし，笠石を花崗岩とした基壇を４周に廻し前面に凸形曲線を有する袖に挟まれた階段３段をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002237"},{"id":"00002239","register_sub_id":"101","register_pk":"103229","name":"末浄水場六号緩速ろ過池","kana":"すえじょうすいじょうろくごうかんそくろかち","category":"生活関連","subcategory":"土木構造物","type_guess":"水道","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市末町1-1","lat":36.513733,"lng":136.698288,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、面積1375㎡、浄水井付","structure_material":"鉄筋コンクリート造","registered":"2001.08.28(平成13.08.28)","register_no":"17 － 0051","desc":"四号緩速ろ過池の西側，ろ過池全体の北西端に位置する。東西方向に延びる通路の下に布設された集水管にろ過水が合流する。小規模ながらも，通路を軸に３基づつ左右対称に配置された浄水井は，周辺景観に溶け込み，市民に広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002239"},{"id":"00002384","register_sub_id":"101","register_pk":"103374","name":"福岡第一発電所","kana":"ふくおかだいいちはつでんしょ","category":"生活関連","subcategory":"建築物","type_guess":"発電","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県白山市河内町福岡日171-2","lat":36.40074607,"lng":136.62724409,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"煉瓦造地下1階地上2階建、瓦葺、建築面積641㎡","structure_material":"煉瓦造地下1階地上2階建","registered":"2001.10.12(平成13.10.12)","register_no":"17 － 0058","desc":"村北西部，国道１５７号沿いの水力発電所の建屋。キングポストトラスを用い，切妻造，煉瓦造２階建とする。要石，迫持石等に石材を用い，上下の半円アーチ・丸窓と，３方向の妻に付く丸窓とコーニスに特徴をもつ外観が，自然景観の中で際だっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002384"}];
